Object.assign(window.XP = window.XP || {}, {"Орша":[54.51,30.42],"Теребовль":[49.55,25.7],"Венеция":[45.44,12.34],"Сить":[58.1,38]});
Object.assign(window.SCENES = window.SCENES || {}, {
  "Немига": {"f": [["кто", "Изяслав, Святослав и Всеволод Ярославичи"], ["против", "Всеслав Брячиславич, князь полоцкий"], ["дата", "3 марта 1067, на Немиге у Минска"], ["итог", "разгром полочан, Всеслав в плену"], ["обман", "крестоцелование под Оршей, затем арест"], ["цена", "Минск взят и разорён, мужчины перебиты"]], "who": [["Изяслав Ярославич", "Киев", "великий князь киевский", "Старший из трёх братьев. Привёл киевлян на Минск и Немигу, затем велел схватить Всеслава.", "izyaslav_yar"], ["Святослав Ярославич", "Чернигов", "князь Чернигова", "Средний брат. Шёл на Минск с черниговским войском и вместе с братьями обманул Всеслава.", "svyatoslav_yar"], ["Всеволод Ярославич", "Переяславль", "князь Переяславля", "Младший из братьев. Участвовал в походе на Минск и в аресте Всеслава под Оршей.", "vsevolod_yar"], ["Всеслав Брячиславич", "Полоцк", "князь Полоцка", "Зимой 1066 увёз колокола Софии из Новгорода. Разбит на Немиге, в Киеве посажен в поруб.", "vseslav"]], "ar": [{"r": ["Полоцк", "Новгород"], "k": "war", "n": "1066 · Всеслав разоряет Новгород", "b": "Псков в 1065-м ему не дался, зато Новгород он в 1066-м разграбил. Современники считали @{vseslav|Всеслава} чародеем: по летописи, он родился с «язвеном» на голове и носил его до смерти.", "x": "*@{vseslav|Всеслав Брячиславич}* был князем Полоцка и правнуком @{vladimir|Владимира Святого}. Его дед @{izyaslav_vl|Изяслав}, сын Владимира и полоцкой княжны @{rogneda|Рогнеды}, остался в Полоцке, а тамошние князья считали, что имеют право на новгородские земли.\n\nВ *1065* году Всеслав не смог взять Псков, зато Новгород в 1066-м разграбил. Ответить ему собрались три сына @{yaroslav_mudry|Ярослава Мудрого}.\n\nСовременники считали Всеслава *чародеем*: по летописи, он родился с «язвеном» на голове и носил его до смерти."}, {"r": ["Киев", "Минск"], "k": "war", "n": "зима 1067 · Изяслав идёт на Минск", "b": "Ответить собрались трое сыновей @{yaroslav_mudry|Ярослава}. @{izyaslav_yar|Изяслав} повёл киевлян в поход зимой, в необычное для войны время. Минск взяли приступом, мужчин перебили, женщин и детей раздали в плен. Через двенадцать лет Минск вырежет @{monomakh|Мономах}: «ни челядина, ни скотины».", "x": "*@{izyaslav_yar|Изяслав}* был старшим из трёх братьев и великим князем киевским. Поход начали зимой, в необычное для войны время, и пошли в полоцкую землю карательной экспедицией.\n\n*Минск* взяли приступом. Мужчин перебили, а женщин и детей раздали в плен.\n\nЧерез двенадцать лет тот же город вырезал уже *@{monomakh|Мономах}*, сын @{vsevolod_yar|Всеволода}: в 1079 году он не оставил в Минске «ни челядина, ни скотины»."}, {"r": ["Чернигов", "Минск"], "k": "war", "n": "зима 1067 · Святослав и Всеволод в походе", "b": "К @{izyaslav_yar|Изяславу} пришёл @{svyatoslav_yar|Святослав} с черниговцами, а с ним младший @{vsevolod_yar|Всеволод}. Правили они втроём, и у каждого был свой город и своя дружина.", "x": "*@{svyatoslav_yar|Святослав}*, средний из братьев, княжил в Чернигове и привёл черниговское войско. С ним шёл младший, *@{vsevolod_yar|Всеволод}*, князь Переяславля.\n\nВместе с @{izyaslav_yar|Изяславом} они правили Русью как *триумвират* сыновей @{yaroslav_mudry|Ярослава Мудрого}. У каждого был свой город и своя дружина, и пока братья держались заодно, они справлялись с теми, кто считал себя обойдённым."}, {"r": ["Минск", "Немига"], "k": "war", "n": "3 марта 1067 · бой на Немиге", "b": "@{vseslav|Всеслав} вывел полочан навстречу братьям и проиграл. Бой шёл в сильный снег, и «Слово о полку Игореве» запомнило поле, где «снопы стелют головами». Оно же сравнивает Всеслава с волком, быстро перебрасывающим дружину с места на место, и скорее восхищается им, а летопись порицает.", "x": "Битва шла в сильный снег на реке *Немиге* у Минска. @{vseslav|Всеслав} вывел полочан навстречу братьям и проиграл.\n\n«Слово о полку Игореве» помнит это поле: на Немиге «снопы стелют головами, молотят цепами булатными». Оно скорее *восхищается* Всеславом, сравнивая его с волком, который быстро перебрасывает дружину с места на место, а «Повесть временных лет» его порицает."}, {"r": ["Орша", "Киев"], "k": "flight", "n": "лето 1067 · Всеслав в киевском порубе", "b": "Братья поцеловали крест, что не тронут @{vseslav|Всеслава}. Он с сыновьями переплыл Днепр у Орши и был схвачен, а клятва нарушена. Меньше чем через год киевляне сами вытащат его из поруба на княжеский стол.", "x": "Летом братья позвали @{vseslav|Всеслава} на переговоры и поцеловали крест, что не причинят ему вреда. Он с двумя сыновьями переплыл Днепр у *Орши*, понадеявшись на клятву, и был схвачен.\n\n@{izyaslav_yar|Изяслав} посадил всех троих в киевский *поруб*, темницу без дверей, откуда не сбежать. Нарушенная клятва подорвала его авторитет и вызвала сочувствие к узнику.\n\nМеньше чем через год киевляне сами вытащили Всеслава из поруба и посадили на *великокняжеский стол*."}], "pin": [["Минск", "взят штурмом, мужчин перебили"], ["Немига", "«снопы стелют головами»"], ["Орша", "крестоцелование и обман"]], "zone": ["Полоцкое", "Киевское"]},
  "Разгром на Альте и восстание": {"f": [["кто", "Изяслав, Святослав, Всеволод Ярославичи"], ["против", "половцы; затем собственные киевляне"], ["битвы", "Альта (сент. 1068, разгром); Снов (ноябрь, победа Святослава)"], ["лозунг", "«Дай нам оружие и коней!»"], ["итог", "Изяслав бежит в Польшу, Всеслав в Киеве"], ["возврат", "1069: Изяслав с поляками, казнь ~70"]], "who": [["Изяслав Ярославич", "Киев", "великий князь киевский", "Проиграл половцам на Альте, отказал киевлянам в оружии и бежал в Польшу. В 1069 вернулся с поляками.", "izyaslav_yar"], ["Святослав Ярославич", "Чернигов", "князь Чернигова", "Пока братья бежали в Киев, в одиночку защитил черниговские земли и разбил половцев на Снове.", "svyatoslav_yar"], ["Всеслав Брячиславич", "Киев", "князь Полоцка, узник", "Сидел в киевском порубе. 15 сентября 1068 толпа освободила его и провозгласила князем.", "vseslav"], ["Болеслав Смелый", "Краков", "король Польши", "Принял бежавшего Изяслава и в 1069 дал ему войско, чтобы вернуть Киев.", "boleslav_sm"]], "ar": [{"r": ["Киев", "Альта"], "k": "war", "n": "сент. 1068 · Альта: половцы бьют Ярославичей", "b": "Началось с разгрома. Осенью 1068 года половцы с ханом Шаруканом впервые пришли на Русь большой ордой и разбили трёх Ярославичей на Альте, где когда-то погиб @{boris|Борис}.", "x": "Осенью *1068* года половцы впервые пришли на Русь большой ордой. Общим вождём, каганом, был хан Шарукан, дед хана @{konchak|Кончака}.\n\nНавстречу вышли @{izyaslav_yar|Изяслав}, @{svyatoslav_yar|Святослав} и @{vsevolod_yar|Всеволод}, три сына @{yaroslav_mudry|Ярослава Мудрого}. На *Альте*, где когда-то погиб @{boris|Борис}, русское войско разбили наголову. Подробностей битвы летописец сообщать не хочет, пишет лишь, что князья побежали."}, {"r": ["Киев", "Краков"], "k": "flight", "n": "сент. 1068 · киевское вече и бегство Изяслава", "b": "С Альты @{izyaslav_yar|Изяслав} ушёл в Киев, где на Торговище собралось вече: киевляне просили оружия и коней, чтобы идти на половцев. Изяслав отказал, и 15 сентября толпа посадила на стол @{vseslav|Всеслава}.", "x": "@{izyaslav_yar|Изяслав} с @{vsevolod_yar|Всеволодом} ушли с Альты в Киев. Там на Торговище собралось *вече*, и киевляне потребовали у великого князя оружия и коней, чтобы идти на половцев. Изяслав отказал.\n\nТолпа освободила из поруба *@{vseslav|Всеслава Полоцкого}*, и 15 сентября его провозгласили великим князем. Изяслав бежал в Польшу к королю @{boleslav_sm|Болеславу Смелому}, мужу своей сестры."}, {"r": ["Чернигов", "Снов"], "k": "war", "n": "нояб. 1068 · Святослав разбивает половцев на Снове", "b": "@{svyatoslav_yar|Святослав} вернулся в Чернигов: помощи от братьев ждать не приходилось. В ноябре он вышел с 3000 человек против 12 000 и разбил половцев на Снове.", "x": "*@{svyatoslav_yar|Святослав}*, средний из Ярославичей, отделился от братьев и вернулся в Чернигов, свой город. Половцы шли по русской земле, и его владения оказались под ударом. Помощи от братьев, бежавших в Киев, ждать не приходилось.\n\nВ ноябре он вышел с *3000* человек против 12 000 половцев и разбил их на реке Снове. Так один князь защитил свой край, пока братья бежали."}, {"r": ["Киев", "Белгород", "Полоцк"], "k": "flight", "n": "весна 1069 · Всеслав уходит в Полоцк", "b": "@{vseslav|Всеслав} просидел в Киеве около семи месяцев. Узнав, что @{izyaslav_yar|Изяслав} идёт с поляками, он ночью ушёл в Белгород, а оттуда в Полоцк, и для киевлян это было полной неожиданностью.", "x": "@{vseslav|Всеслав} просидел в Киеве около *семи месяцев*. Узнав, что Изяслав идёт с польским войском, он вышел навстречу с дружиной, но увидел неравенство сил и ночью ушёл в Белгород, а оттуда в Полоцк. Для киевлян это было полной неожиданностью.\n\nЕщё лет десять он воевал с Ярославичами: то побеждал, то бывал разбит, но былых высот не достиг. Умер он в *1101* году, поделив Полоцкое княжество между семью сыновьями, и княжество вскоре распалось."}, {"r": ["Краков", "Киев"], "k": "war", "n": "весна 1069 · Изяслав возвращается в Киев", "b": "Король @{boleslav_sm|Болеслав} дал @{izyaslav_yar|Изяславу} войско, и Изяслав сел в Киеве второй раз. Сын Изяслава казнил в Киеве около семидесяти освободителей @{vseslav|Всеслава}. Королю вскоре пришлось убираться восвояси: поляки разошлись по волостям, и местные жители начали их истреблять. Но Изяслав остался зависим от младших братьев, и в 1073 году они прогнали его снова.", "x": "Король *@{boleslav_sm|Болеслав II}* дал @{izyaslav_yar|Изяславу} войско, потому что был женат на его сестре. Весной 1069 года они пошли на Киев, @{vseslav|Всеслав} бежал, и Изяслав вернулся на стол.\n\nЕго сын *@{mstislav_iz_st|Мстислав}* казнил в Киеве около семидесяти человек, освобождавших Всеслава.\n\nИзяслав ещё не раз вернётся и уйдёт, но единства на Руси больше не было: эпоха, по Акунину, надломилась именно в *1068* году."}], "pin": [["Альта", "на месте гибели Бориса"], ["Снов", "3000 бьют 12 000"], ["Киев", "вече: «Дай оружие и коней»"]], "zone": ["Киевское", "Половецкая степь"]},
  "Стугна": {"f": [["кто", "Святополк Изяславич, Мономах, Ростислав Всеволодович"], ["против", "половцы хана Тугоркана"], ["дата", "26 мая 1093"], ["войско", "у Святополка около 800 отроков, остальные не названы"], ["потеря", "утонул Ростислав, брат Мономаха"], ["итог", "разорение Торческа и порубежья"]], "who": [["Святополк Изяславич", "Киев", "великий князь киевский", "Посадил половецких послов в яму и пошёл на половцев с 800 отроками, не послушав советов мириться.", "svyatopolk_izy"], ["Владимир Мономах", "Чернигов", "князь Чернигова", "Пришёл на помощь Святополку. Предлагал мириться, но киевляне настояли на бое.", "monomakh"], ["Ростислав Всеволодович", "Переяславль", "младший брат Мономаха", "Князь Переяславля. Утонул в разлившейся Стугне при бегстве русского войска.", "rostislav_vsev"], ["Тугоркан", "Половцы", "хан, тесть Святополка", "Осадил Торческ. После победы на Стугне взял город и разорил округу.", "tugorkan"]], "ar": [{"r": ["Половцы", "Торческ"], "k": "war", "n": "весна 1093 · Тугоркан осаждает Торческ", "b": "В апреле умер @{vsevolod_yar|Всеволод}, последний из сыновей Ярослава, а половцы @{tugorkan|Тугоркана} осадили Торческ на Роси, город «чёрных клобуков».", "x": "В апреле *1093* года умер @{vsevolod_yar|Всеволод}, последний из сыновей @{yaroslav_mudry|Ярослава Мудрого}. По лествичному праву стол перешёл к старшему из племянников, @{svyatopolk_izy|Святополку Изяславичу}, сыну старшего из Ярославичей.\n\nПоловцы хана *@{tugorkan|Тугоркана}* рассчитывали поживиться в начавшейся смуте и сразу осадили Торческ на Роси, город «чёрных клобуков». Святополк посадил их послов в яму, и осады было не избежать."}, {"r": ["Киев", "Стугна"], "k": "war", "n": "26 мая 1093 · Святополк идёт к Стугне", "b": "Послов @{tugorkan|Тугоркана} @{svyatopolk_izy|Святополк} посадил в яму, мириться и откупаться не захотел, а бояре его поддержали: «Мы хотим биться». По Акунину, из-за такой неразумности нашествие и состоялось.", "x": "@{svyatopolk_izy|Святополк} выступил из Киева с *800* отроками. Остальных воинов летопись не называет: для боя с ордой, осаждавшей Торческ, войско было малым.\n\nМириться и откупаться от половцев он не захотел, и киевские бояре его поддержали: «Мы хотим *биться*». По Акунину, из-за этой неразумности нашествие и состоялось. Войско пошло к Стугне, которая в мае разлилась."}, {"r": ["Чернигов", "Стугна"], "k": "war", "n": "май 1093 · Мономах приходит на помощь", "b": "@{monomakh|Мономах} княжил в Чернигове и мог занять Киев, но уступил его двоюродному брату. Он предлагал мириться, однако поддался киевским боярам: войско переправилось через разлившуюся Стугну, и русские побежали.", "x": "*@{monomakh|Мономах}*, сын умершего @{vsevolod_yar|Всеволода}, княжил в Чернигове. Занять Киев он мог, но добровольно уступил его двоюродному брату @{svyatopolk_izy|Святополку}: тот был сыном старшего из Ярославичей.\n\nТеперь Мономах пришёл на помощь и предлагал мириться, но уступил киевским боярам. 26 мая войско переправилось через разлившуюся *Стугну*, и на правом берегу русские побежали."}, {"r": ["Переяславль", "Стугна"], "k": "war", "n": "май 1093 · Ростислав тонет в Стугне", "b": "Переяславльский князь @{rostislav_vsev|Ростислав}, младший брат @{monomakh|Мономаха}, утонул на глазах у старшего, и тот помнил этот день всю жизнь. Торческ пал, а @{svyatopolk_izy|Святополку} пришлось взять в жёны дочь @{tugorkan|Тугоркана}. В 1094-м @{oleg_gor|Олег Гориславич} сам привёл половцев в Чернигов, усобицы пошли по всей Руси, и князьям пришлось договариваться: через четыре года они встретятся в Любече.", "x": "*@{rostislav_vsev|Ростислав Всеволодович}*, младший брат @{monomakh|Мономаха}, княжил в Переяславле. Он пришёл вместе с братом к @{svyatopolk_izy|Святополку}.\n\nПри бегстве Ростислав утонул в Стугне на глазах Мономаха, тело вытащили позже. Мономах *помнил* этот день всю жизнь.\n\n*Торческ* пал, половцы сожгли окрестные города и сёла и увели в степь множество рабов. Святополку пришлось заключить унизительный мир и взять в жёны дочь хана @{tugorkan|Тугоркана}."}], "pin": [["Стугна", "26 мая: разгром русских"], ["Торческ", "пал, окрестности сожжены"], ["Киев", "после Всеволода сел Святополк"]], "zone": ["Киевское", "Половецкая степь"]},
  "Любечский съезд": {"f": [["кто", "Святополк, Мономах, Давыд и Олег Святославичи, Давыд Игоревич, Василько Ростиславич"], ["лозунг", "«Каждый да держит отчину свою»"], ["удел", "Киев у Святополка, Чернигов у Давыда Святославича"], ["дата", "1097; ослепление Василька 5 ноября"], ["итог", "страна поделена на вотчины, мир ненадолго"]], "who": [["Святополк Изяславич", "Киев", "великий князь киевский", "Получил по договору Киев и Туров. Вскоре поверил наговору и велел схватить Василька.", "svyatopolk_izy"], ["Владимир Мономах", "Переяславль", "князь Переяславля", "Открыл съезд призывом прекратить усобицы, пока половцы разоряют землю. Потом пошёл на Святополка за Василька.", "monomakh"], ["Олег Святославич", "Новгород-Северский", "князь Новгорода-Северского", "Съезд прошёл в его городе Любече. Вместе с братьями сохранил отцовские земли.", "oleg_gor"], ["Давыд Игоревич", "Владимир-Волынский", "князь Владимира-Волынского", "Получил Владимир-Волынский. Оклеветал Василька перед Святополком, и того ослепили.", "davyd_igor"], ["Василько Ростиславич", "Теребовль", "князь Теребовля", "Держал Теребовль вместе с братом Володарем. В ноябре 1097 схвачен в Киеве и ослеплён.", "vasilko"]], "ar": [{"r": ["Переяславль", "Любеч"], "k": "trade", "n": "осень 1097 · Мономах зовёт князей в Любеч", "b": "Мысль созвать съезд принадлежала @{monomakh|Мономаху}, внуку Ярослава Мудрого. Начал он словами: «Зачем губим Русскую землю… а половцы землю нашу несут розно».", "x": "Много лет князья воевали друг с другом, а половцы тем временем жгли русские земли. Мысль созвать съезд принадлежала *@{monomakh|Мономаху}*, внуку @{yaroslav_mudry|Ярослава Мудрого} и князю Переяславля.\n\nСъезд шестерых князей прошёл в *Любече*, в городе @{oleg_gor|Олега}. Мономах начал: «Зачем губим Русскую землю… а половцы землю нашу несут розно»."}, {"r": ["Киев", "Любеч"], "k": "trade", "n": "осень 1097 · «каждый да держит отчину свою»", "b": "Договорились по формуле «Каждый да держит отчину свою»: @{svyatopolk_izy|Святополк} остался в Киеве и Турове, @{davyd_igor|Давыд Игоревич} получил Владимир-Волынский, а братья Ростиславичи Перемышль и Теребовль.", "x": "*@{svyatopolk_izy|Святополк Изяславич}*, внук @{yaroslav_mudry|Ярослава Мудрого}, был великим князем киевским. По договору он получил Киев и Туров.\n\nРешили: «Каждый да держит *отчину* свою». @{monomakh|Мономаху} остались Переяславль, Смоленск и Ростов. Святославичи взяли Чернигов, @{davyd_igor|Давыд Игоревич}, сын @{igor_yar|Игоря Ярославича}, Владимир-Волынский, а братья Ростиславичи Перемышль и Теребовль."}, {"r": ["Новгород-Северский", "Любеч"], "k": "trade", "n": "осень 1097 · Олег и Святославичи", "b": "Святославичи, Давыд, Олег и Ярослав, сохранили Чернигов, Новгород-Северский, Муром и Рязань, но к киевскому столу Ольговичей больше не допускали, и они этого не забыли. А @{oleg_gor|Олега}, три года назад приведшего на Русь половцев, прозвали Гориславичем.", "x": "*@{oleg_gor|Олег Святославич}*, князь Новгорода-Северского, был сыном @{svyatoslav_yar|Святослава Ярославича}, одного из трёх Ярославичей. В 1094 году он привёл на Русь половцев, за что получил прозвище Гориславич.\n\nСвятославичи, @{davyd_sv|Давыд}, Олег и @{yaroslav_sv|Ярослав}, сохранили Чернигов, Новгород-Северский, Муром и Рязань. Потомки Олега стали зваться *Ольговичами*: черниговская отчина осталась за ними, но к киевскому престолу их больше не допускали."}, {"r": ["Теребовль", "Киев"], "k": "trade", "n": "5 нояб. 1097 · Василька хватают в Киеве", "b": "Едва съезд кончился, Давыд внушил @{svyatopolk_izy|Святополку}, что @{vasilko|Василько} Теребовльский собирает силы на Киев. Василька позвали «на именины», и 5 ноября схватили и заковали.", "x": "*@{vasilko|Василько Ростиславич}* княжил в Теребовле вместе с братом @{volodar|Володарем}. Их отец @{rostislav_vl|Ростислав}, внук @{yaroslav_mudry|Ярослава Мудрого}, погиб отравленным в Тьмутаракани. У Василька было войско из «чёрных клобуков», и он готовился к походу на Польшу.\n\nВладимирский князь *@{davyd_igor|Давыд Игоревич}* внушил @{svyatopolk_izy|Святополку}, что Василько собирает силы, чтобы захватить Киев. Василька позвали в Киев «на именины», и 5 ноября его схватили и заковали."}, {"r": ["Киев", "Белгород"], "k": "war", "n": "нояб. 1097 · Василька ослепляют в Белгороде", "b": "Ночью @{vasilko|Василька} в телеге повезли в Белгород и ослепили: на Руси так расправились с соперником впервые. Князья ужаснулись, @{monomakh|Мономах} пошёл на @{svyatopolk_izy|Святополка} войной, а Давыд лишился Владимира-Волынского. Лишь в 1103 году у Долобского озера князья решили идти на половцев сообща.", "x": "@{svyatopolk_izy|Святополк} передал пленника @{davyd_igor|Давыду}, и ночью Василька в телеге повезли в Белгород, небольшой город под Киевом. Там ему выкололи *глаза*. Позже Святополк открестился и свалил вину на Давыда.\n\nОслепление соперников из царского рода пришло из Византии, и на Руси его применили впервые. Князья ужаснулись: «Сего не было в роде нашем». *@{monomakh|Мономах}* назвал это злодеянием, невиданным на Руси, и пошёл на Святополка войной.\n\nДавыд лишился Владимир-Волынского, а на съезде *1100* года ему отвели несколько волостей на западе Руси."}], "pin": [["Любеч", "съезд шести князей, 1097"], ["Белгород", "выкололи глаза Васильку"]], "zone": ["Киевское", "Черниговское"]},
  "Крестовый поход в степь": {"f": [["кто", "Мономах, Святополк Изяславич, Давыд Святославич"], ["путь", "Переяславль, Сула, Хорол, Псёл, Ворскла, Донец, Шарукань"], ["дата", "февр.–апр. 1111 (Великий пост)"], ["поход", "духовенство шло с войском, пели молебны"], ["итог", "Шарукань сдалась, Сугров сожжён, победа на Сальнице"], ["последствие", "половцы отходят за Дон; ненадолго спокойно"]], "who": [["Владимир Мономах", "Переяславль", "князь Переяславля", "Убедил князей идти в степь зимой, на Великом посту, пока половецкие кони тощие, и шёл в авангарде.", "monomakh"], ["Святополк Изяславич", "Киев", "великий князь киевский", "Согласился на поход и повёл киевские полки.", "svyatopolk_izy"], ["Давыд Святославич", "Чернигов", "князь Чернигова", "Третий вождь похода, привёл черниговских воинов.", "davyd_sv"]], "ar": [{"r": ["Переяславль", "Сула", "Шарукань"], "k": "war", "n": "Великий пост 1111 · князья идут к Донцу", "b": "@{monomakh|Мономах} убедил @{svyatopolk_izy|Святополка} и Давыда Святославича не ждать половцев. Войско прошло Сулу, Хорол, Псёл, Голтву и Ворсклу и вышло к Северскому Донцу. К этому походу Мономах шёл почти двадцать лет.", "x": "*@{monomakh|Мономах}* убедил двух других князей идти на половцев, не дожидаясь, пока те придут сами. @{svyatopolk_izy|Святополк Изяславич}, великий князь киевский, и @{davyd_sv|Давыд Святославич} из Чернигова были, как и он, внуками @{yaroslav_mudry|Ярослава Мудрого}.\n\nВышли на Великом посту, пока половецкие кони тощие. Миновали Сулу, Хорол, Псёл, Голтву, Ворсклу и дошли до *Северского Донца*. К этому походу вели почти двадцать лет усилий Мономаха, созывавшего съезды князей."}, {"r": ["Шарукань", "Сугров"], "k": "war", "n": "март 1111 · Шарукань сдаётся, Сугров горит", "b": "Первой лежала Шарукань, зимний стан половцев: её жители откупились рыбой и вином и сдались без боя. Сугров сожгли дотла, удар пришёлся по становищам, а не по заставам.", "x": "Первой на пути стояла *Шарукань*. Летом половцы кочевали по куреням, а зимой собирались в зимовьях, которые летопись называет городами. Шарукань была таким зимним станом, и её жители сдались без боя, откупившись рыбой и вином.\n\n*Сугров* сожгли дотла. Удар пришёлся по самим зимним станам, а не по заставам на границе."}, {"r": ["Сугров", "Сальница"], "k": "war", "n": "апр. 1111 · победа на Сальнице", "b": "На Сальнице в открытом поле половцев разбили, взяли много пленных, скота и лошадей. @{monomakh|Мономаха}, после этого похода и ещё двух, 1103 и 1116 годов, стали считать первым защитником Руси, хотя киевским князем оставался @{svyatopolk_izy|Святополк}, который «к войне не был охотник».", "x": "Главная битва прошла на *Сальнице* в открытом поле. С войском шли священники и пели молитвы, поэтому поход зовут крестовым.\n\nВзяли много пленных, скота и лошадей. Половцы ушли за Дон и на Кавказ и *несколько лет* не лезли на Русь.\n\nЗа этот поход и ещё два, 1103 и 1116 годов, @{monomakh|Мономаха} стали считать *первым защитником Руси*. Окончательно мощь Степи была сломлена именно в 1111 году."}], "pin": [["Шарукань", "сдалась, дала рыбу и вино"], ["Сугров", "сожжён дотла"], ["Сальница", "главная битва похода"]], "zone": ["Половецкая степь", "Переяславское"]},
  "Мономах в Киеве": {"f": [["кто", "Владимир Мономах"], ["смерть", "16 апр. 1113 — Святополк Изяславич"], ["бунт", "погром двора тысяцкого Путяты и ростовщиков"], ["закон", "«Устав о резах» — потолок на проценты"], ["дата", "Мономах в Киеве с 20 апр. 1113"], ["сыновья", "Мстислав, Ярополк, Вячеслав, Юрий — по городам"]], "who": [["Владимир Мономах", "Переяславль", "князь Переяславля", "Сильнейший князь Руси. Киевляне позвали его, он пришёл 20 апреля и принял Устав о резах.", "monomakh"], ["Святополк Изяславич", "Киев", "князь киевский, †1113", "Умер 16 апреля 1113. Киевляне ненавидели его за соляную монополию и ростовщиков.", "svyatopolk_izy"], ["Давыд Святославич", "Чернигов", "князь Чернигова", "Старший в роду по лествичному праву. Не стал спорить за Киев.", "davyd_sv"]], "ar": [{"r": ["Киев", "Переяславль"], "k": "trade", "n": "16 апр. 1113 · умирает Святополк", "b": "Пока @{svyatopolk_izy|Святополк} был жив, киевляне терпели высокие проценты ростовщиков и соляную монополию. Когда он умер, вече потянулось к @{monomakh|Мономаху}, хотя старшим считался @{davyd_sv|Давыд Святославич}, и тот спорить не стал.", "x": "*16 апреля 1113* года умер @{svyatopolk_izy|Святополк}. При нём киевляне платили ростовщикам высокие проценты, а соль продавалась по монополии.\n\nВече сразу потянулось к *@{monomakh|Мономаху}*, сыну @{vsevolod_yar|Всеволода} и князю Переяславля. Но он медлил: по лествичному праву старшим считался его двоюродный брат @{davyd_sv|Давыд Святославич} Черниговский. Давыд за Киев спорить не стал."}, {"r": ["Переяславль", "Киев"], "k": "trade", "n": "20 апр. 1113 · Мономах приходит в Киев", "b": "Знать написала ему: «Приди, князь, в Киев, а не придёшь, много зла будет». Он пришёл 20 апреля и первым делом принял «Устав о резах», ограничивший проценты по долгам. Старшие князья согласились.", "x": "Пока Мономах раздумывал, в Киеве начался бунт. Громили двор тысяцкого *@{putyata|Путяты}*, жгли дома ростовщиков, грабили монастыри.\n\nКиевская знать написала @{monomakh|Мономаху}: «Приди, князь, в Киев, а не придёшь, много зла будет». Он пришёл 20 апреля и первым делом принял «*Устав о резах*», ограничивший проценты по долгам. Старшие князья согласились."}, {"r": ["Киев", "Новгород", "Ростов"], "k": "migration", "n": "1113–1125 · Мономах рассаживает сыновей", "b": "В Новгороде @{monomakh|Мономах} посадил @{mstislav_great|Мстислава}, в Ростове @{yuri_dolg|Юрия}, будущего Долгорукого, а в 1118-м заставил новгородских бояр присягнуть в Киеве. Три четверти русских земель он взял под себя или раздал сыновьям, а ссоры гасил браками между ветвями рода. Это был последний взлёт Киевской Руси, и править дальше выпало старшему сыну.", "x": "@{monomakh|Мономах} правил *двенадцать лет*. Три четверти русских земель он взял под личное управление или раздал сыновьям: в Новгороде княжил @{mstislav_great|Мстислав}, в Ростове @{yuri_dolg|Юрий}, будущий Долгорукий.\n\nКонфликты он по возможности гасил браками между ветвями рода. В *1118* году заставил новгородских бояр явиться в Киев и присягнуть, а в 1119 присоединил Минское княжество.\n\nПоловцы после разгрома 1111 года вели себя тихо. Это короткое княжение стало *последним взлётом* Киевской Руси."}], "pin": [["Киев", "бунт, затем Устав о резах"], ["Новгород", "княжит сын Мстислав"], ["Ростов", "княжит сын Юрий"], ["Чернигов", "Давыд — старший по лествице"]], "zone": ["Киевское", "Переяславское"]},
  "Мономах и Мстислав Великий": {"f": [["кто", "Мономах (до 1125), Мстислав Великий (1125–1132)"], ["смерть", "19 мая 1125 Мономах; 15 апр. 1132 Мстислав"], ["полоцк", "1129 — Всеславичи сосланы в Царьград"], ["чудь", "1130 — взят Юрьев (Тарту)"], ["итог", "после 1132 держава рассыпается на уделы"]], "who": [["Владимир Мономах", "Киев", "великий князь киевский", "Умер 19 мая 1125 на Альте, похоронен в Киевской Софии.", "monomakh"], ["Мстислав Владимирович", "Белгород", "сын Мономаха, «Великий»", "После отца сел в Киеве. Подчинил Полоцк и чудь и держал в повиновении Чернигов, Переяславль и Новгород.", "mstislav_great"], ["Всеволод Мстиславич", "Новгород", "сын Мстислава", "Князь Новгорода. В 1130 новгородцы ходили на чудь и взяли Юрьев.", "vsevolod_mst"], ["Давыд Всеславич", "Полоцк", "князь Полоцка", "Один из Всеславичей, высланных Мстиславом в Царьград в 1129 за нарушенную клятву.", "davyd_vseslavich"]], "ar": [{"r": ["Киев", "Полоцк"], "k": "war", "n": "1125–1127 · Мстислав идёт на Полоцк", "b": "@{monomakh|Мономах} умер 19 мая 1125 года и лёг в Киевской Софии. Киев перешёл к старшему сыну Мстиславу, а в 1127-м он пошёл на потомков @{vseslav|Всеслава Чародея} в Полоцк, и Всеславичи уступили.", "x": "@{monomakh|Мономах} умер *19 мая 1125* года и был похоронен в Киевской Софии. Киев перешёл к старшему сыну @{mstislav_great|Мстиславу}. Его мать @{gita|Гита} была дочерью английского короля @{harold|Гарольда}, погибшего при Гастингсе, а потомки прозвали Мстислава Великим.\n\nПолоцкое княжество принадлежало потомкам @{vseslav|Всеслава Чародея}. В *1127* году Мстислав пошёл на Полоцк, и Всеславичи уступили."}, {"r": ["Полоцк", "Константинополь"], "k": "flight", "n": "1129 · Мстислав высылает полоцких князей", "b": "Полоцкие князья нарушили клятву, и в 1129 году Мстислав отправил их с жёнами и детьми в Царьград. В Полоцке он посадил сына @{izyaslav_mst|Изяслава}, но независимость княжества вернулась после его смерти в 1132 году.", "x": "Полоцкие князья нарушили клятву, и в *1129* году Мстислав отправил их с жёнами и детьми в Царьград. Среди высланных был @{davyd_vseslavich|Давыд Всеславич}. Византия принимала таких политических ссыльных.\n\nВ Полоцке Мстислав посадил сына @{izyaslav_mst|Изяслава}. Так закончилась более чем вековая независимость княжества. Но после смерти Мстислава в *1132* году Полоцк вернул своего князя."}, {"r": ["Новгород", "Юрьев"], "k": "war", "n": "1130 · новгородцы ходят на чудь", "b": "Князь @{vsevolod_mst|Всеволод Мстиславич} с новгородцами взял и сжёг чудский Юрьев. Пока жив был Мстислав, Чернигов, Переяславль и Новгород сидели смирно, а после его смерти Новгород стал выбирать князей сам.", "x": "В *1130* году новгородцы ходили на чудь, и князь Новгорода @{vsevolod_mst|Всеволод Мстиславич}, сын @{mstislav_great|Мстислава}, взял чудский Юрьев (Тарту) и сжёг его. Мстислав ходил и на литву, а до самой смерти держал в повиновении Чернигов, Переяславль и Новгород.\n\nПосле его смерти *15 апреля 1132* года Новгород стал выбирать князей сам. Мономашичи, потомки @{monomakh|Мономаха}, начали воевать с Ольговичами, потомками @{oleg_gor|Олега Гориславича}, и друг с другом. Мономах и Мстислав остались последними, кого слушалась вся Русь."}], "pin": [["Альта", "здесь умер Мономах, 1125"], ["Полоцк", "княжит сын Мстислава Изяслав"], ["Юрьев", "Тарту взят и сожжён"]], "zone": ["Киевское", "Полоцкое"]},
  "Новгородская республика": {"f": [["кто", "новгородцы, князь Всеволод Мстиславич"], ["обвинения", "не защищал смердов, ушёл в Переяславль, бросил войско"], ["дата", "весна–лето 1136"], ["итог", "Всеволод изгнан, князя приглашают по договору"], ["власть", "вече, посадник, тысяцкий, затем архиепископ"], ["новый князь", "Святослав Ольгович, брат киевского князя"]], "who": [["Всеволод Мстиславич", "Новгород", "князь Новгорода", "Внук Мономаха, княжил с 1117. В 1136 новгородцы арестовали его с семьёй и прогнали.", "vsevolod_mst"], ["Святослав Ольгович", "Новгород-Северский", "князь Новгорода-Северского", "Брат киевского князя Всеволода Ольговича. Новгородцы позвали его княжить на своих условиях.", "svyatoslav_olg"]], "ar": [{"r": ["Новгород", "Переяславль"], "k": "flight", "n": "1136 · новгородцы выгоняют Всеволода", "b": "Новгородцы любили его отца, а сам @{vsevolod_mst|Всеволод} популярности не снискал: «не блюдёт смердов». Весной 1136-го его арестовали, несколько недель держали на княжьем дворе и выслали: «Ты посиди у нас, пока мы поищем себе другого князя».", "x": "*@{vsevolod_mst|Всеволод Мстиславич}* был сыном @{mstislav_great|Мстислава Великого} и внуком @{monomakh|Мономаха}. Новгородцы любили его отца, а сам он популярности не снискал. Княжил он с 1117 года.\n\nК 1136 году накопились обиды: князь самовольно уехал в Переяславль в *1132* году, бросил новгородцев в битве на Жданьей горе и «не блюдёт смердов».\n\nВесной 1136 года его с семьёй арестовали, несколько недель продержали в княжьем дворе и *выслали*: «Ты посиди у нас, пока мы поищем себе другого князя»."}, {"r": ["Новгород-Северский", "Новгород"], "k": "migration", "n": "1136 · Святослав Ольгович занимает стол", "b": "Новгородцы позвали @{svyatoslav_olg|Святослава Ольговича}, но князь стал наёмным военачальником и судьёй, договоры с ним записывали, а нарушителей изгоняли. Его брат @{vsevolod_olg|Всеволод Ольгович} тем временем готовился забрать Киев.", "x": "Новгородцы позвали *@{svyatoslav_olg|Святослава Ольговича}*, князя Новгорода-Северского. Он был Ольговичем, из рода @{oleg_gor|Олега Гориславича}, и братом @{vsevolod_olg|Всеволода Ольговича}, будущего киевского князя. Мономашичи с Ольговичами враждовали, но город не захотел быть игрушкой в их борьбе.\n\nС тех пор вече на *Ярославовом дворище* выбирало посадника и тысяцкого. Князь стал наёмным военачальником и судьёй и не мог владеть землёй в Новгородской земле. Договоры с князьями записывали, нарушителей изгоняли. С 1156 года избирали и архиепископа."}], "pin": [["Новгород", "1136: вече изгнало князя"], ["Псков", "помог изгнать Всеволода"], ["Ладога", "ладожане против князя"]], "zone": ["Новгородская земля"]},
  "Москва": {"f": [["кто", "Юрий Долгорукий и Святослав Ольгович"], ["дата", "4 апр. 1147, первое упоминание в летописи"], ["слова", "«Приди ко мне, брате, в Москов»"], ["подарок", "пард (барс), «обед силён»"], ["укрепление", "1156 — рубленые стены и ров"], ["цель", "союз против Изяслава Мстиславича за Киев"]], "who": [["Юрий Долгорукий", "Суздаль", "князь Ростова и Суздаля", "Воевал за Киев и собирал союзников. В его письме Святославу впервые названа Москва.", "yuri_dolg"], ["Святослав Ольгович", "Новгород-Северский", "князь Новгорода-Северского", "Союзник Юрия. 4 апреля 1147 приехал в Москву с сыном Олегом, получил пир и барса.", "svyatoslav_olg"], ["Изяслав Мстиславич", "Киев", "великий князь киевский", "Соперник Юрия за Киев. Против него Юрий и собирал союзников.", "izyaslav_mst"]], "ar": [{"r": ["Новгород-Северский", "Москва"], "k": "trade", "n": "апр. 1147 · Святослав едет в Москов", "b": "@{yuri_dolg|Юрию} нужны были союзники против @{izyaslav_mst|Изяслава} Мстиславича, и он написал Святославу: «Приди ко мне, брате, в Москов». Тот явился с сыном @{oleg_svy_br|Олегом} и небольшой дружиной. Это первое известие о Москве.", "x": "*@{svyatoslav_olg|Святослав Ольгович}*, князь Новгорода-Северского, был из Ольговичей, потомков @{oleg_gor|Олега Гориславича}. Он стал союзником @{yuri_dolg|Юрия Долгорукого} в борьбе за Киев против @{izyaslav_mst|Изяслава Мстиславича} из Мономашичей. Сам Юрий тоже был Мономашичем, но встал на сторону Ольговичей, потому что хотел сесть в Киеве.\n\nЮрий писал ему: «Приди ко мне, брате, в *Москов*». Святослав явился с сыном @{oleg_svy_br|Олегом} и небольшой дружиной. Это первое известие о Москве."}, {"r": ["Суздаль", "Москва"], "k": "trade", "n": "4 апр. 1147 · пир у Юрия", "b": "Князья «любезно поцеловались», @{yuri_dolg|Юрий} получил в подарок охотничьего барса, а 4 апреля дал «обед силён». Первый кремль на Боровицком холме поставили только в 1156 году, и, по Акунину, не он: сам Юрий тогда сидел в Киеве.", "x": "*@{yuri_dolg|Юрий Долгорукий}* был шестым сыном @{monomakh|Мономаха} и князем Ростова и Суздаля. Москов тогда была пограничным боярским селом на Москве-реке, на дороге с севера на юг. Её звали и Кучково, по боярину @{kuchka|Кучке}.\n\nКнязья «любезно поцеловались», и *4 апреля* Юрий дал «обед силён», торжественный пир. Подарком стал барс, византийская аристократическая забава.\n\nПозже Юрий велел убить Кучку, а село присоединил к своим владениям. Первый кремль на Боровицком холме поставили в *1156* году, но, по Акунину, не он: Юрий сидел в Киеве, а севером правил сын @{andrey_bogol|Андрей}."}, {"r": ["Суздаль", "Киев"], "k": "war", "n": "1149 · Юрий берёт Киев", "b": "Союз пригодился: в 1149 году @{yuri_dolg|Юрий} захватил Киев и пошёл добивать @{izyaslav_mst|Изяслава} под Луцком. Половцев в авангарде вёл его сын @{andrey_bogol|Андрей}. Город ещё не раз переходил из рук в руки: окончательно Юрий сел в Киеве лишь в 1155-м, а в 1157-м умер. Москва тогда была одним из его сёл, и судьба Руси решалась там, куда ушёл его сын Андрей.", "x": "В 1146 году Киев у Ольговичей взял *@{izyaslav_mst|Изяслав Мстиславич}*, племянник @{yuri_dolg|Юрия}. Юрий воевал с ним ради стола, хотя оба были Мономашичами.\n\nВ *1149* году Юрий захватил Киев и пошёл добивать соперника под Луцком, где авангардом из половцев командовал его сын @{andrey_bogol|Андрей}. Город несколько раз переходил из рук в руки.\n\nОкончательно Юрий сел в Киеве лишь в *1155* году и умер там в 1157-м."}], "pin": [["Москва", "первое упоминание, 4 апр. 1147"]], "zone": ["Владимиро-Суздальское", "Черниговское"]},
  "Андрей Боголюбский": {"f": [["кто", "Андрей Юрьевич, сын Долгорукого"], ["переезд", "1155 · из Вышгорода во Владимир с иконой"], ["дата", "1157 · бояре зовут в Ростов и Суздаль"], ["столица", "Владимир-на-Клязьме, замок Боголюбово"], ["строит", "Успенский собор, Золотые ворота (1164), Покров на Нерли (1165)"], ["стиль", "самовластец, без веча, без боярского совета"]], "who": [["Андрей Боголюбский", "Вышгород", "сын Юрия Долгорукого", "Сидел в Вышгороде, в 1155 ушёл на север с иконой Богоматери. Позже сделал столицей Владимир.", "andrey_bogol"], ["Юрий Долгорукий", "Киев", "отец Андрея, великий князь", "Посадил сына в Вышгороде, когда взял Киев. Умер в Киеве 15 мая 1157.", "yuri_dolg"]], "ar": [{"r": ["Вышгород", "Владимир"], "k": "flight", "n": "1155 · Андрей уходит из Вышгорода", "b": "Началось с самоуправства. Отец велел @{andrey_bogol|Андрею} быть в Вышгороде, а тот ушёл на север и увёз чудотворную икону Богоматери, обставив дело так, будто этого хочет сама икона.", "x": "*@{andrey_bogol|Андрей}* был вторым из одиннадцати сыновей @{yuri_dolg|Юрия Долгорукого}, а по матери наполовину половцем, внуком хана @{aepa|Аепы}. Когда Юрий в 1155 году сел в Киеве, он велел сыну быть в Вышгороде, крепости на подходах к столице.\n\nАндрей самовольно ушёл на север. Из Вышгородского замка он увёз чудотворную икону Богоматери и обставил дело так, будто исполняет волю иконы. Она стала главной святыней *Владимира*."}, {"r": ["Владимир", "Ростов"], "k": "migration", "n": "1157 · бояре зовут Андрея на стол", "b": "Когда @{yuri_dolg|Юрий} умер в Киеве, ростовские бояре позвали @{andrey_bogol|Андрея} на стол. Он прогнал из земли братьев и племянников, а вдову отца, царевну Ольгу, с детьми отослал в Константинополь.", "x": "@{yuri_dolg|Юрий} умер в Киеве в *1157* году. @{andrey_bogol|Андрея} поддержала городская верхушка Суздаля, Ростова и Владимира, ростовские бояре позвали его на стол, и формально он стал князем всей отцовской отчины.\n\nЖить в старых боярских городах он не стал. Из своей земли он прогнал братьев и племянников, а вдову отца, византийскую царевну *Ольгу*, с детьми отослал в Константинополь."}, {"r": ["Ростов", "Владимир"], "k": "migration", "n": "1157 · столица во Владимире, а не в Ростове", "b": "В Ростове и Суздале решало вече, а во Владимире @{andrey_bogol|Андрей} чувствовал себя в безопасности. Старшую дружину он разогнал и опирался на торговцев и ремесленников.", "x": "Столицей @{andrey_bogol|Андрей} сделал небольшой *Владимир-на-Клязьме*. В Суздале и Ростове было самоуправление и сильная знать, там решали на вече и могли прогнать князя. Во Владимире он чувствовал себя в безопасности.\n\nАндрей правил как *самодержец*. Он разогнал непокорных бояр и старшую дружину, вече не признавал и опирался на торговцев и ремесленников. Киев он считал лишь «старшим городом»."}, {"r": ["Владимир", "Боголюбово"], "k": "migration", "n": "ок. 1158 · Андрей строит Боголюбово", "b": "Рядом с Владимиром выросла резиденция Боголюбово, от неё князь и получил прозвище, а не за любовь к Богу. Золотыми воротами (1164) он хотел затмить Киев, и зодчих для них звал из Западной Европы. А в 1169 году, через двенадцать лет после воцарения, он послал войско на сам Киев.", "x": "По рассказу, на месте, где @{andrey_bogol|Андрею} явилась Богоматерь, он поставил храм и устроил резиденцию *Боголюбово* в пяти километрах от Владимира. Прозвище Боголюбский он получил по этому селу, а не за любовь к Богу, как замечает Акунин.\n\nЗодчих для каменных храмов Андрей звал из Западной Европы. Он возвёл Успенский собор, *Золотые ворота* (1164) и церковь Покрова на Нерли (1165). Золотыми воротами он хотел затмить Киев."}], "pin": [["Владимир", "Успенский собор и ворота"], ["Боголюбово", "отсюда прозвище Боголюбский"]], "zone": ["Владимиро-Суздальское"]},
  "Андрей разоряет Киев": {"f": [["кто", "Андрей Боголюбский, воевода Мстислав Андреевич"], ["против", "Мстислав Изяславич, князь киевский"], ["войско", "11 князей, суздальцы, смоляне, рязанцы, черниговцы"], ["дата", "8 марта 1169, грабёж 2–3 дня"], ["итог", "Киев разорён, Глеб Юрьевич — князь Киева"], ["суть", "великим князем стал тот, кто живёт во Владимире"]], "who": [["Андрей Боголюбский", "Владимир", "князь Владимира", "Собрал против Киева 11 князей, но сам остался во Владимире и посадил в Киеве брата Глеба.", "andrey_bogol"], ["Мстислав Андреевич", "Владимир", "сын Андрея", "Командовал объединённым войском при штурме Киева.", "mstislav_andr"], ["Мстислав Изяславич", "Киев", "князь киевский", "Три дня оборонял город и бежал на Волынь.", "mstislav_izy"], ["Роман Ростиславич", "Смоленск", "князь Смоленска", "Привёл смоленских Ростиславичей в войско Андрея.", "roman_rost"], ["Глеб Юрьевич", "Переяславль", "князь Переяславля, брат Андрея", "Участвовал в походе, потом Андрей посадил его князем в Киеве.", "gleb_yur"]], "ar": [{"r": ["Владимир", "Киев"], "k": "war", "n": "1168 · Андрей собирает войско на Киев", "b": "После смерти великого князя @{rostislav_mst|Ростислава} в 1167 году за Киев началась война, и в нём сел @{mstislav_izy|Мстислав Изяславич}. @{andrey_bogol|Андрей} в 1168 году собрал войско одиннадцати князей и поставил воеводой сына @{mstislav_andr|Мстислава}.", "x": "После смерти великого князя @{rostislav_mst|Ростислава} в *1167* году между претендентами на Киев началась большая война. В городе сел @{mstislav_izy|Мстислав Изяславич}, сын @{izyaslav_mst|Изяслава Мстиславича}, отнявшего Киев у Ольговичей в 1146 году.\n\n@{andrey_bogol|Андрей}, сын @{yuri_dolg|Долгорукого}, решил показать, что слово Киева не определяет судьбу Руси. В *1168* году он собрал войско одиннадцати князей, воеводой поставил сына @{mstislav_andr|Мстислава}. К Киеву подошли в начале марта 1169 года."}, {"r": ["Смоленск", "Киев"], "k": "war", "n": "1169 · смоляне и другие идут к Киеву", "b": "В поход пошли смоляне Ростиславичей, рязанцы, муромцы, полочане и брат @{andrey_bogol|Андрея} @{gleb_yur|Глеб}. Отряды смолян привёл @{roman_rost|Роман Ростиславич}: при его отце Смоленск стал отдельным княжеством.", "x": "*Ростиславичи* были сыновьями @{rostislav_mst|Ростислава Мстиславича}, внука @{monomakh|Мономаха}, который княжил в Смоленске и с 1159 по 1167 год был великим князем киевским. Смоленск при нём стал отдельным княжеством.\n\nНа Киев смоляне пошли в одной коалиции с рязанцами, муромцами, полочанами и @{gleb_yur|Глебом}, братом @{andrey_bogol|Андрея}. Отряды привёл *@{roman_rost|Роман Ростиславич}*."}, {"r": ["Чернигов", "Киев"], "k": "war", "n": "8 март 1169 · штурм Киева", "b": "Подошли в начале марта, к осаде присоединились и черниговцы. @{mstislav_izy|Мстислав Изяславич} держался три дня, но чёрные клобуки изменили. Киевляне заперлись, а не открыли ворота сильнейшему, и город впервые в истории взяли штурмом.", "x": "К осаде присоединились и черниговские князья. @{mstislav_izy|Мстислав Изяславич} оборонялся *три дня*, но «чёрные клобуки» из его войска изменили, а собственная дружина биться насмерть не захотела.\n\nКиевляне допустили ошибку. Вместо того чтобы, как всегда, выгнать князя и открыть ворота более сильному, они заперлись в расчёте на крепкие стены. Поэтому *8 марта 1169* года город взяли штурмом, впервые в его истории, мечом."}, {"r": ["Киев", "Владимир"], "k": "trade", "n": "март 1169 · грабёж Киева", "b": "Грабёж шёл два-три дня: горели церкви, вывозили иконы, книги и колокола, сотни киевлян продали в рабство. @{andrey_bogol|Андрей} не остановил этого, потому что упадок соперника ему был выгоден.", "x": "Грабёж шёл два-три дня. Горели церкви, вывозили иконы, книги, колокола и священные сосуды, а сотни киевлян продали в *рабство*. Не пощадили ни Софийский, ни Десятинный храм.\n\n@{andrey_bogol|Андрей} не только не остановил бесчинства, но, похоже, поощрял их: он основал новую столицу, Владимир, и ему был выгоден упадок города-соперника. После *1169* года Киев уже не был главным центром власти, хотя митрополит остался там."}, {"r": ["Киев", "Владимир-Волынский"], "k": "flight", "n": "март 1169 · в Киеве сидит брат Андрея", "b": "@{mstislav_izy|Мстислав Изяславич} ушёл на Волынь, в свою отчину. @{andrey_bogol|Андрей} посадил в Киеве брата @{gleb_yur|Глеба} и остался во Владимире. За семнадцать лет правления он успел настроить против себя всех, кто сидел рядом, и самые опасные враги ждали не в Киеве, а в собственном замке Боголюбово, где его бояре давно считали, сколько им терпеть.", "x": "@{mstislav_izy|Мстислав Изяславич} бежал на *Волынь*, в свою отчину, которую ему выделил отец.\n\n@{andrey_bogol|Андрей} посадил в Киеве брата @{gleb_yur|Глеба}, князя Переяславля, а сам остался во Владимире. Такого на Руси ещё не бывало: великий князь жил не в Киеве. По Акунину, это была *революция*: власть привязали не к месту, а к личности правителя, и где он, там и власть."}], "pin": [["Киев", "8 марта 1169: грабёж 2–3 дня"]], "zone": ["Киевское", "Владимиро-Суздальское"]},
  "Убийство Боголюбского": {"f": [["кто", "Яким Кучкович с зятем Петром, Анбал, слуга Ефрем Моизович"], ["жертва", "Андрей Боголюбский"], ["дата", "ночь на 29 июня 1174"], ["место", "замок Боголюбово"], ["после", "грабёж, усобица Ростиславичей и Юрьевичей"], ["итог", "1176 · Владимир берёт Всеволод Юрьевич"]], "who": [["Андрей Боголюбский", "Боголюбово", "князь Владимира", "Правил самовластно, держал при себе чужеземцев. Убит заговорщиками в ночь на 29 июня 1174.", "andrey_bogol"], ["Яким Кучкович", "Боголюбово", "боярин-заговорщик", "Брат казнённого Андреем Кучковича. Вместе с зятем Петром собрал недовольных.", "yakim_kuchkovich"], ["Анбал", "Боголюбово", "княжеский ключник", "Ясин (осетин). Заранее выкрал оружие князя, чтобы тот не смог защищаться.", "ambal"], ["Михалко Юрьевич", "Чернигов", "брат Андрея", "После убийства занял владимирский стол, но умер в 1176.", "mikhalko"], ["Всеволод Юрьевич", "Чернигов", "младший брат Андрея", "Вместе с Михалко пошёл за столом на север. С 1176 князь Владимира.", "vsevolod_bg"]], "ar": [{"r": ["Боголюбово", "Владимир"], "k": "war", "n": "29 июня 1174 · убийство в Боголюбове", "b": "@{yakim_kuchkovich|Яким Кучкович} собрал недовольных: «Нынче казнил он Кучковича, а завтра казнит и нас». Около двадцати заговорщиков напились в погребе и взломали дверь, а ключник @{ambal|Анбал} заранее выкрал оружие, и князь защищался голыми руками.", "x": "*Семнадцать лет* @{andrey_bogol|Андрей} правил неограниченно, и бояре боялись его всё больше. Он казнил одного из Кучковичей, и брат казнённого, *@{yakim_kuchkovich|Яким Кучкович}*, собрал недовольных: «Нынче казнил он Кучковича, а завтра казнит и нас».\n\nВ ночь на 29 июня около двадцати заговорщиков напились в княжеском погребе и взломали дверь опочивальни. Ключник *@{ambal|Анбал}* заранее выкрал оружие, и Андрей, человек сильный, защищался голыми руками. Замок разграбили, а нагое тело долго лежало во дворе."}, {"r": ["Ростов", "Владимир"], "k": "war", "n": "1174 · Ростов и Владимир делят племянники", "b": "Ростов и Суздаль презирали новый Владимир и называли владимирцев «холопами-каменщиками», посадников убивали. Верх взяли племянники @{andrey_bogol|Андрея}: @{mstislav_rost|Мстислав} сел в Ростове, @{yaropolk_rost|Ярополк} во Владимире.", "x": "После убийства в княжестве началась борьба за власть. «Старые» города, Ростов и Суздаль, презирали «новый» Владимир: бояре называли владимирцев «холопами-каменщиками». По округе убивали княжеских посадников, и смуту в столице остановили, только пронеся по улицам чудотворную *икону Богоматери*.\n\nВ *1174* году верх взяли Ростиславичи, племянники @{andrey_bogol|Андрея}, сыновья его старшего брата @{rostislav_yur|Ростислава}. Старший, @{mstislav_rost|Мстислав}, сел в Ростове, младший, @{yaropolk_rost|Ярополк}, во Владимире."}, {"r": ["Чернигов", "Владимир"], "k": "war", "n": "1175–76 · владимирцы зовут Михалко, потом Всеволода", "b": "@{yaropolk_rost|Ярополк} расставил на должности пришлых людей, и владимирцы позвали @{mikhalko|Михаила}: в 1175 году он разбил племянников. В 1176-м Михаил умер, и присягнули его младшему брату @{vsevolod_bg|Всеволоду}, ещё совсем молодому.", "x": "Владимирцам не нравилось, что @{yaropolk_rost|Ярополк} расставил на должности пришлых людей, и они позвали *@{mikhalko|Михаила Юрьевича}*, брата @{andrey_bogol|Андрея}. В 1175 году он пришёл с дружиной, разбил племянников и сел во Владимире.\n\nМихаил давно хворал и в *1176* году умер. Тогда владимирцы присягнули его младшему брату @{vsevolod_bg|Всеволоду}, последнему сыну @{yuri_dolg|Долгорукого}. Он был ещё совсем молод и серьёзным соперником не выглядел."}, {"r": ["Юрьев-Польский", "Ростов"], "k": "war", "n": "1176 · Всеволод бьёт Мстислава у Юрьева-Польского", "b": "Мстислав опоздал, а делить землю отказался. У Юрьева-Польского @{vsevolod_bg|Всеволод} победил, пленных Ростиславичей ослепил, и летопись добавляет, что они вскоре прозрели. Ростовцы покорились, и князем всей земли стал он.", "x": "Ростовцы позвали @{mstislav_rost|Мстислава Ростиславича}, но он *опоздал*: Владимир уже присягнул @{vsevolod_bg|Всеволоду}. Тот предложил поделить землю и отдать Ростов сопернику. Мстислав отказался, рассчитывая забрать всё княжество.\n\nУ *Юрьева-Польского* Всеволод победил, и Мстислав бежал. Ростовцы покорились окончательно. Пленных Ростиславичей владимирцы требовали казнить, и Всеволод ослепил их сам. Летопись добавляет, что вскоре оба *прозрели*."}], "pin": [["Боголюбово", "здесь убит, ночь на 29 июня"], ["Владимир", "усобица за стол до 1176"]], "zone": ["Владимиро-Суздальское"]},
  "Всеволод Большое Гнездо": {"f": [["кто", "Всеволод Юрьевич, сын Долгорукого"], ["правил", "1176–1212, 36 лет"], ["победа", "27 июня 1177, Колокша: разгром Ростиславичей"], ["поход", "1183 · на Волжскую Булгарию"], ["дети", "8 сыновей, 4 дочери — «Большое Гнездо»"], ["ошибка", "1212: стол Юрию, не старшему Константину"]], "who": [["Всеволод Юрьевич", "Владимир", "великий князь Владимира", "Младший брат Андрея. С 1176 правил Владимиром 36 лет, разбил Ростиславичей, жёг Рязань, ходил на Булгар.", "vsevolod_bg"], ["Мстислав Ростиславич", "Ростов", "племянник Всеволода", "Ростовцы звали его на владимирский стол, но Всеволод успел раньше. Разбит на Колокше.", "mstislav_rost"], ["Глеб Ростиславич", "Рязань", "князь Рязани", "Союзник Ростиславичей против Всеволода. В 1177 Рязань сожжена.", "gleb_rost"], ["Константин Всеволодович", "Ростов", "старший сын Всеволода", "Получил Ростов, но в 1212 был обойдён: стол отец отдал Юрию.", "konstantin_vsev"]], "ar": [{"r": ["Владимир", "Колакша"], "k": "war", "n": "27 июня 1177 · Колокша", "b": "Сев во Владимире, @{vsevolod_bg|Всеволод} сразу получил соперника: племянник @{mstislav_rost|Мстислав} вернулся с зятем @{gleb_rost|Глебом Рязанским} и сжёг Москву. Всеволод месяц стоял на Колокше, пока у врагов не кончились припасы, и разбил их.", "x": "@{vsevolod_bg|Всеволод} родился в *1154* году, он был сыном @{yuri_dolg|Долгорукого} от гречанки. Ребёнком он вместе с матерью был изгнан братом @{andrey_bogol|Андреем} и вырос в Константинополе, при дворе императора @{manuel_i|Мануила}. В 1176 году он сел во Владимире.\n\nЕго соперником был племянник *@{mstislav_rost|Мстислав Ростиславич}*, сын его старшего брата @{rostislav_yur|Ростислава}. Мстислав вернулся с зятем @{gleb_rost|Глебом Рязанским} и сжёг Москву. Всеволод преградил им путь на Колокше и месяц стоял, пока у врагов не кончились припасы. Тогда они атаковали и 27 июня 1177 года были разгромлены."}, {"r": ["Владимир", "Рязань"], "k": "war", "n": "1177 · Всеволод сжигает Рязань", "b": "@{gleb_rost|Глеб Рязанский} был союзником Ростиславичей, и после Колокши @{vsevolod_bg|Всеволод} сжёг его город. Рязань с тех пор ходила в его воле, а когда в 1207–08 годах бунтовала, он снова её сжёг, но жителей расселил.", "x": "*@{gleb_rost|Глеб Рязанский}* был зятем @{mstislav_rost|Мстислава Ростиславича} и союзником Ростиславичей. После Колокши @{vsevolod_bg|Всеволод} взял Рязань и сжёг её. Рязань с тех пор ходила в его воле.\n\nПозже она не раз бунтовала. В *1207* году Всеволод раскрыл заговор рязанских князей с его врагами Ольговичами, но арестованных вскоре выпустил. В следующем году рязанцы захватили княжеских представителей и некоторых засыпали в погребах. Тогда Всеволод снова сжёг город, но жителей не истребил, а расселил."}, {"r": ["Владимир", "Булгар"], "k": "war", "n": "1183 · булгарский поход и Новгород", "b": "Поход 1183 года против Волжской Булгарии @{vsevolod_bg|Всеволод} выиграл. Новгород он подчинил без войны и около тридцати лет назначал ему князей. Пока он укреплял север, на юге князья дрались друг с другом и ходили на половцев без его ведома, и один такой поход дал материал для целой поэмы.", "x": "Булгары, по словам Акунина, создавали трудности волжской торговле, и поход *1183* года против Волжской Булгарии @{vsevolod_bg|Всеволод} выиграл.\n\nНовгород он подчинил без войны: поддерживал там своих сторонников и около *тридцати лет* назначал городу князей по своей воле. Новгородцы просили у него князей.\n\nПрозвище Большое Гнездо ему дали восемь сыновей и четыре дочери. Перед смертью в *1212* году он передал стол не старшему @{konstantin_vsev|Константину}, а @{yuri_vsev|Юрию}, и это обернулось Липицей."}], "pin": [["Колакша", "здесь разбиты племянники"], ["Владимир", "Дмитриевский собор"]], "zone": ["Владимиро-Суздальское", "Муромо-Рязанское"]},
  "Поход Игоря Святославича": {"f": [["кто", "Игорь Святославич, брат Всеволод, сын Владимир"], ["против", "хан Кончак и хан Гзак"], ["дата", "23 апр.–12 мая 1185"], ["затмение", "1 мая 1185 · дружина в страхе"], ["итог", "плен, бегство Игоря, ответный набег Кончака"], ["памятник", "«Слово о полку Игореве»"]], "who": [["Игорь Святославич", "Новгород-Северский", "князь Новгорода-Северского", "Пошёл на половцев без согласия великого князя, потерпел поражение на Каяле, попал в плен и бежал.", "igor_svy"], ["Всеволод Святославич", "Курск", "брат Игоря, князь Курска", "«Буй-тур». Шёл с Игорем и в плен попал вместе с ним.", "vsevolod_svy"], ["Владимир Игоревич", "Путивль", "сын Игоря", "Князь Путивля. В плену женился на дочери Кончака, Свободе.", "vladimir_igor"], ["Святослав Всеволодович", "Киев", "великий князь киевский", "Не знал о походе и не давал на него согласия.", "svyatoslav_vsev"], ["Кончак", "Половцы", "хан половцев", "С Гзаком разбил русских на Каяле, потом напал на Переяславль и Путивль.", "konchak"]], "ar": [{"r": ["Новгород-Северский", "Путивль", "Каяла"], "k": "war", "n": "23 апр. 1185 · Игорь выходит в степь", "b": "@{igor_svy|Игорь} княжил на границе со степью и пошёл на половцев, не спросив великого князя. С ним шли брат @{vsevolod_svy|Всеволод Курский}, сын @{vladimir_igor|Владимир} и племянник Олег. Замысел был дальний: «поискати града Тьмутороканя». Дружина дрогнула, когда затмилось солнце, и Игорь ответил: «Лучше быть убитым, чем полоненым».", "x": "*@{igor_svy|Игорь Святославич}* княжил в небольшом Новгород-Северском княжестве на границе со степью. Он был из черниговских Ольговичей, внуком @{oleg_gor|Олега Гориславича}, а по матери наполовину половцем, внуком хана @{aepa|Аепы}.\n\nНе спросив великого князя @{svyatoslav_vsev|Святослава Киевского}, он решил пойти на половцев и прославиться. Вышли 23 апреля с братом @{vsevolod_svy|Всеволодом Курским}, сыном @{vladimir_igor|Владимиром} и племянником Олегом. Замысел был дальний: «поискати града *Тьмутороканя*».\n\n1 мая затмилось солнце, и дружина испугалась. Игорь ответил: «*Лучше быть убитым, чем полоненым*»."}, {"r": ["Каяла", "Новгород-Северский"], "k": "flight", "n": "май 1185 · Каяла и плен", "b": "У Каялы первую схватку выиграли, но пока делили добычу, @{konchak|Кончак} с @{gzak|Гзаком} собрали орды. Бой шёл три дня, 12 мая раненый @{igor_svy|Игорь} сдался, а потом ночью бежал с помощью «половчина» @{ovlur|Овлура}.", "x": "У Каялы первую схватку выиграли: опрокинули передовые заставы и захватили добычу. Пока победители делили её, хан *@{konchak|Кончак}* с ханом @{gzak|Гзаком} собрали ближние орды. Бой шёл три дня.\n\nДружина @{vsevolod_svy|Всеволода} заняла оборону, и @{igor_svy|Игорь} пришёл на помощь не сразу. 12 мая раненый Игорь *сдался*.\n\nПленных князей держали с почётом. Ночью с помощью «половчина @{ovlur|Овлура}» Игорь *бежал*, добрался до Донца и вернулся в Новгород-Северский."}, {"r": ["Половцы", "Путивль"], "k": "war", "n": "лето 1185 · Кончак идёт на Путивль", "b": "Победа развязала Кончаку руки, и он напал на Переяславль и Путивль. О походе сложено «Слово о полку Игореве», а по нему историки восстанавливают и другие русско-половецкие войны. Их было не меньше сорока. Пока северские князья ссорились со степью, на юго-западе поднимался князь, у которого к чужим усобицам было своё дело: он собирал земли в кулак.", "x": "@{konchak|Кончак} воспользовался победой и напал на Переяславль и *Путивль*.\n\nСын @{igor_svy|Игоря} @{vladimir_igor|Владимир}, князь Путивля, остался в плену и женился на дочери Кончака, *@{svoboda|Свободе}*. Игорь и Кончак прежде вместе воевали против общих врагов, и вся война выглядит скорее семейной ссорой.\n\nОб этом походе сложено «*Слово о полку Игореве*». По нему историки восстанавливают и другие русско-половецкие войны, а их было не меньше сорока."}], "pin": [["Каяла", "10–12 мая: разгром, плен Игоря"]], "zone": ["Половецкая степь", "Черниговское"]},
  "Роман Галицкий": {"f": [["кто", "Роман Мстиславич"], ["удел", "Волынь с 1188, Галич с 1199"], ["дата", "1199 — объединение"], ["Киев", "ок. 1202 — занят, посажен свой князь"], ["смерть", "19 июня 1205, у Завихоста на Висле"], ["дети", "Даниил (4 года) и Василько"]], "who": [["Роман Мстиславич", "Владимир-Волынский", "князь Волыни и Галича", "С 1188 княжил во Владимире-Волынском, в 1199 занял Галич и соединил два княжества.", "roman_mst"], ["Владимир Ярославич", "Галич", "последний галицкий Ярославич", "Умер в 1199. Бояре, не желая венгерского короля, позвали Романа.", "vladimir_yar_gal"], ["Рюрик Ростиславич", "Киев", "тесть Романа, князь киевский", "Роман занял Киев при нём, а позже постриг Рюрика с семьёй в монахи.", "rurik_rost"], ["Лешек Белый", "Краков", "князь Кракова", "В 1205 его люди убили Романа в засаде у Завихоста.", "leshek"]], "ar": [{"r": ["Владимир-Волынский", "Галич"], "k": "war", "n": "1199 · бояре зовут Романа в Галич", "b": "@{roman_mst|Роман} с 1188 года княжил на Волыни. Когда в 1199 году умер последний галицкий @{yaroslav_vsev|Ярославич}, бояре позвали его, лишь бы не получить венгерского короля. Роман соединил два княжества.", "x": "*@{roman_mst|Роман Мстиславич}* был сыном @{mstislav_izy|Мстислава Изяславича}, того самого, что бежал из Киева от @{andrey_bogol|Андрея}. Роман с *1188* года княжил в Волыни, во Владимире-Волынском.\n\nГаличем правили потомки @{rostislav_vl|Ростислава Владимировича}, внука @{yaroslav_mudry|Ярослава Мудрого}. В 1199 году умер последний галицкий Ярославич, и *бояре*, лишь бы не получить венгерского короля, позвали Романа.\n\nОн соединил Галицкое и Волынское княжества и жёстко давил бояр: «Не передавив *пчёл*, мёду не есть»."}, {"r": ["Владимир-Волынский", "Киев"], "k": "war", "n": "ок. 1202 · Роман берёт Киев", "b": "@{roman_mst|Роман} воевал с половцами, литвой и ятвягами, а папа Иннокентий III предлагал ему королевскую корону за переход в католичество. По преданию, он ответил, что в ином мече не нуждается. Около 1202 года он занял Киев и посадил там своего человека.", "x": "Роман воевал с половцами, литвой и ятвягами и ходил в Польшу. Слава о нём дошла до Рима: папа *Иннокентий III* предлагал королевскую корону при условии перехода в католичество. По преданию, Роман ответил, что в ином мече не нуждается.\n\nОколо *1202* года он занял Киев и посадил там своего человека. Роман был женат на дочери @{rurik_rost|Рюрика Ростиславича}. Рассорившись с тестем, он постриг в монахи и Рюрика, и его жену, и дочь, то есть собственную жену."}, {"r": ["Галич", "Висла"], "k": "war", "n": "июнь 1205 · Роман гибнет у Завихоста", "b": "В 1205 году @{roman_mst|Роман} попал в засаду @{leshek|Лешека Белого} на Висле и был убит. Сыновья остались детьми, страна рассыпалась, а @{daniil|Даниил} соберёт её лишь к 1245 году. Киев же, где сидел человек Романа, разорили ещё в 1203-м: изгнанные Романом князья вернулись с половцами.", "x": "В *1205* году Роман попал в засаду @{leshek|Лешека Белого}, князя Кракова, у Завихоста на Висле и был убит. По польским хроникам, тело разрубили.\n\nЕго сыновьям, *@{daniil|Даниилу}* и @{vasilko_rom|Василько}, было совсем мало лет. Созданная Романом страна сразу рассыпалась, началась боярская смута, и на Галич напали венгры.\n\nДаниил позже вернёт отцовскую державу: объединение Галицко-Волынского княжества завершится только в *1245* году."}], "pin": [["Галич", "расправа с боярами"], ["Висла", "тело, по хроникам, рассекли"]], "zone": ["Галицкое", "Волынское"]},
  "Падение Киева и Царьграда": {"f": [["Киев", "янв. 1203: Рюрик, Всеволод Чермный и половцы"], ["удар", "разграблены Подол и Гора, церкви и монастыри"], ["Царьград", "13 апр. 1204: IV Крестовый поход"], ["флот", "венецианский, дож Энрико Дандоло"], ["итог", "латинская империя, греческая Византия распалась"], ["для Руси", "потеря главного торгового партнёра на юге"]], "who": [["Рюрик Ростиславич", "Овруч", "бывший князь Киева", "Вытеснен из Киева Романом. В январе 1203 вернулся с союзниками и разграбил город.", "rurik_rost"], ["Всеволод Чермный", "Чернигов", "князь Чернигова", "Ольгович, союзник Рюрика. Привёл на Киев черниговцев и половцев.", "vsevolod_cherm"], ["Роман Мстиславич", "Галич", "зять Рюрика, князь Галича", "Прежде занял Киев. Позже, рассорившись с Рюриком, постриг его в монахи.", "roman_mst"], ["Энрико Дандоло", "Венеция", "дож Венеции", "Вёл венецианский флот IV Крестового похода, взявший Константинополь.", "dandolo"]], "ar": [{"r": ["Чернигов", "Киев"], "k": "war", "n": "янв. 1203 · Чермный идёт на Киев", "b": "@{vsevolod_cherm|Всеволод Чермный} из Ольговичей по традиции ладил с половцами и привёл на Киев их вместе с черниговцами. Союзником был @{rurik_rost|Рюрик Ростиславич}, которого зять @{roman_mst|Роман} вытеснил из Киева, и тот вернулся мстить.", "x": "*@{vsevolod_cherm|Всеволод Чермный}*, князь Чернигова, был из Ольговичей, потомков @{oleg_gor|Олега Гориславича}. Эти князья по традиции ладили с половцами, и на Киев он привёл черниговцев и половцев.\n\nСоюзником Чермного был *@{rurik_rost|Рюрик Ростиславич}* из смоленских Ростиславичей, сын @{rostislav_mst|Ростислава Мстиславича}. @{roman_mst|Роман Галицкий}, его зять, вытеснил Рюрика из Киева, и тот вернулся мстить.\n\nЭто был второй погром Киева за *тридцать четыре* года: первый в 1169 году устроили суздальцы @{andrey_bogol|Андрея Боголюбского}."}, {"r": ["Овруч", "Киев"], "k": "war", "n": "янв. 1203 · Рюрик берёт Киев", "b": "Взяли и ограбили Подол и Гору, церкви и монастыри, жителей уводили в плен и не щадили ни священников, ни монахов. @{rurik_rost|Рюрик} занимал Киев семь раз и ни разу не удержался.", "x": "Взяли и ограбили *Подол* и Гору, церкви и монастыри. Жителей уводили в плен. Не щадили ни священников, ни монахов, что говорит о крайней степени ожесточения.\n\n@{rurik_rost|Рюрик} занимал Киев *семь раз* и ни разу не удержался. Он сел там и в этот раз, но рассорился с зятем @{roman_mst|Романом}, и тот постриг его в монахи. Через два года Роман погиб, и Рюрик, которому было за шестьдесят, снова стал князем."}, {"r": ["Венеция", "Константинополь"], "k": "war", "n": "13 апр. 1204 · крестоносцы берут Царьград", "b": "Крестоносцы на венецианских кораблях три дня грабили Царьград и посадили в нём латинского императора. Флотом Четвёртого крестового похода командовал дож @{dandolo|Дандоло}. Византия распалась, Русь потеряла главного партнёра, от которого получала веру, книги и мастеров, а Киев и без того терял торговое значение, потому что Константинополь торговал с Западом через Венецию. На северо-востоке тем временем стареющий @{vsevolod_bg|Всеволод Большое Гнездо} решал, кому оставить свои земли.", "x": "Флотом Четвёртого крестового похода командовал венецианский дож *@{dandolo|Энрико Дандоло}*. Крестоносцы три дня грабили Константинополь и посадили на трон латинского императора.\n\nГреческая Византия распалась, и Русь потеряла главного партнёра на юге: оттуда она получала веру, книги и мастеров. Киев уже давно терял торговое значение: с конца XI века Константинополь вёл торговлю с Западом через *Венецию*."}], "pin": [["Киев", "Подол и Гора разграблены"], ["Константинополь", "создана Латинская империя"]], "zone": ["Киевское", "Византия"]},
  "Липица": {"f": [["победители", "Константин Ростовский, Мстислав Удатный, смоляне, новгородцы"], ["побеждённые", "Юрий Всеволодович и Ярослав Всеволодович"], ["дата", "22 апр. 1216, у Юрьева-Польского"], ["потери", "по летописи 9233 убитых у Юрия, пленных 60"], ["итог", "Константин — великий князь, Юрий в Городце"], ["причина", "1212: стол Юрию вместо старшего Константина"]], "who": [["Юрий Всеволодович", "Владимир", "великий князь Владимира", "Получил стол по воле отца в 1212. Проиграл Липицу, бежал во Владимир, потом уехал в Городец.", "yuri_vsev"], ["Ярослав Всеволодович", "Переяславль-Залесский", "брат Юрия", "Воевал вместе с Юрием, после разгрома бежал в Переяславль.", "yaroslav_vsev"], ["Константин Всеволодович", "Ростов", "старший брат Юрия", "Обойдённый старший сын Всеволода. Позвал на помощь Мстислава и после победы стал великим князем.", "konstantin_vsev"], ["Мстислав Удатный", "Новгород", "князь Новгорода", "Привёл новгородцев и смолян и ударил первым. Новгородцы сняли сапоги и бились босыми.", "mstislav_ud"], ["Владимир Рюрикович", "Смоленск", "князь Смоленска", "Привёл смоленские отряды на помощь Константину.", "vladimir_rur"]], "ar": [{"r": ["Новгород", "Ростов"], "k": "war", "n": "весна 1216 · Мстислав ведёт новгородцев в Ростов", "b": "Обойдённый @{konstantin_vsev|Константин} позвал на помощь @{mstislav_ud|Мстислава Удатного}. Тот княжил в Новгороде, сидеть на месте не умел и привёл новгородцев.", "x": "Перед смертью в *1212* году @{vsevolod_bg|Всеволод Большое Гнездо} собирался оставить стол старшему сыну @{konstantin_vsev|Константину}, а Ростов отдать @{yuri_vsev|Юрию}. Константин не хотел делить княжество, и рассерженный отец назначил наследником Юрия.\n\nОбойдённый Константин позвал на помощь *@{mstislav_ud|Мстислава Удатного}*, сына @{mstislav_hrab|Мстислава Храброго}, победителя @{andrey_bogol|Боголюбского} под Вышгородом. Мстислав княжил в Новгороде, не умел сидеть на месте и привёл новгородцев."}, {"r": ["Смоленск", "Ростов"], "k": "war", "n": "весна 1216 · смоляне и Константин в Ростове", "b": "Смолян вёл @{vladimir_rur|Владимир Рюрикович}, сын князя, семь раз занимавшего Киев. В Ростове они соединились с @{konstantin_vsev|Константином}, а @{yuri_vsev|Юрий} и @{yaroslav_vsev|Ярослав} стояли им навстречу у Юрьева-Польского.", "x": "Смоленскими отрядами командовал *@{vladimir_rur|Владимир Рюрикович}*, сын @{rurik_rost|Рюрика Ростиславича} из смоленских Ростиславичей, потомков Мономаха. Его отец семь раз занимал Киев и ни разу там не удержался.\n\nСмоляне вместе с новгородцами соединились с @{konstantin_vsev|Константином} в Ростове. Против них стояли @{yuri_vsev|Юрий} и *@{yaroslav_vsev|Ярослав}*, его брат, у Юрьева-Польского."}, {"r": ["Ростов", "Липица"], "k": "war", "n": "22 апр. 1216 · Липица", "b": "@{yuri_vsev|Юрий} и @{yaroslav_vsev|Ярослав} были уверены, что новгородцы и смоляне драться не станут. @{mstislav_ud|Мстислав} ударил первым и, по рассказу, трижды пронёсся сквозь вражеские ряды, разя топором, привязанным к руке.", "x": "@{yuri_vsev|Юрий} и @{yaroslav_vsev|Ярослав} были *уверены*, что новгородцы и смоляне драться не станут, и готовились беспечно.\n\n*@{mstislav_ud|Мстислав}* ударил первым. Пешие новгородцы разулись и рубились босиком. Сам Удатный, по рассказу, трижды пронёсся сквозь вражеские ряды, разя топором, привязанным к руке.\n\nЭто самое кровопролитное сражение междоусобиц. По летописи, у Юрия и Ярослава погибло *9233* человека, а в плен попало лишь 60."}, {"r": ["Липица", "Владимир"], "k": "flight", "n": "после Липицы · Юрий бежит во Владимир", "b": "Суздальская рать развалилась, и @{yuri_vsev|Юрий} бежал во Владимир, а потом в Городец, который ему отдали в удел. Князья после @{vsevolod_bg|Всеволода} не умели договариваться, и земля раздробилась на Суздальское, Ярославское, Переяславское и другие княжества.", "x": "Суздальская рать развалилась. @{yuri_vsev|Юрий} бежал во Владимир, а потом в *Городец*, который ему отдали в удел. Великим князем вопреки воле отца стал @{konstantin_vsev|Константин}.\n\nПосле @{vsevolod_bg|Всеволода} князья уже не умели договариваться миром. Владимирская земля *раздробилась* на Суздальское, Ярославское, Переяславское, Ростовское и другие княжества, и к приходу монголов Северо-Восток был разобщён."}, {"r": ["Липица", "Переяславль-Залесский"], "k": "flight", "n": "после Липицы · Ярослав бежит, Мстислав уходит", "b": "@{yaroslav_vsev|Ярослав} бежал в Переяславль-Залесский, где княжил. Мстислав ушёл из Новгорода «поискать Галича» и сел там, победив венгров и поляков. Оттуда в 1223 году он и отправится в степь.", "x": "*@{yaroslav_vsev|Ярослав Всеволодович}*, брат @{yuri_vsev|Юрия}, бежал в Переяславль-Залесский, где княжил. Он воевал вместе с Юрием против старшего брата @{konstantin_vsev|Константина}.\n\n@{mstislav_ud|Мстислав} после победы вернулся в Новгород и через некоторое время сказал горожанам: «Хочу поискать *Галича*, а вас не забуду». Он уехал навсегда, и уже в 1223 году поведёт русских князей на Калку."}], "pin": [["Липица", "9233 убитых по летописи"], ["Городец", "Юрию отдан в удел"], ["Владимир", "здесь сел Константин"]], "zone": ["Владимиро-Суздальское", "Новгородская земля"]},
  "Калка": {"f": [["русские", "Мстислав Киевский, Мстислав Черниговский, Мстислав Удатный, Даниил Волынский"], ["против", "монголы Джебе и Субэдэй, половцы Котяна на русской стороне"], ["дата", "31 мая 1223, река Калка"], ["потери", "6 князей убито, лишь каждый десятый вернулся"], ["казнь", "князей положили под доски и пировали"], ["итог", "монголы уходят на Волгу, вернутся в 1237"]], "who": [["Мстислав Удатный", "Галич", "князь Галича", "Зять Котяна. Созвал князей в Киев и повёл русских в степь, после разгрома бежал за Днепр.", "mstislav_ud"], ["Мстислав Романович", "Киев", "великий князь киевский", "Отсиделся в укреплённом лагере, сдался по обещанию Плоскини и был убит под досками.", "mstislav_roman"], ["Мстислав Святославич", "Чернигов", "князь Чернигова", "Один из трёх главных князей похода. Погиб при разгроме.", "mstislav_cherm"], ["Котян", "Половцы", "хан половцев", "Просил помощи: «Нынче нашу землю взяли, а завтра вашу». Его половцы побежали первыми.", "kotyan"], ["Джебе и Субэдэй", "Прикавказье", "монгольские полководцы", "Прошли за Кавказ, разбили аланов и половцев, затем разгромили русских на Калке."]], "ar": [{"r": ["Прикавказье", "Половцы"], "k": "war", "n": "1222–23 · монголы бьют половцев", "b": "@{dzhebe|Джебе} и @{subedei|Субэдэй} совершили первый европейский рейд монголов: прошли за Кавказ, разбили аланов и лезгин и вышли в Половецкую степь. Князья давно роднились с половцами, так что беда степи касалась и Руси.", "x": "@{dzhebe|Джебе} и @{subedei|Субэдэй} вели монгольскую армию @{chingis|Чингис-хана}. Это был первый европейский рейд монголов: они прошли за Кавказ, разбили аланов и лезгин и вышли в *Половецкую степь*.\n\nРусские князья давно роднились с половцами и звали их в союзники. По меньшей мере дважды великие князья женились на половчанках, так что беда *половцев* касалась и Руси."}, {"r": ["Половцы", "Галич"], "k": "flight", "n": "зима 1223 · Котян в Галиче", "b": "Хан @{kotyan|Котян} ушёл к зятю в Галич, где Мстислав сел, победив венгров и поляков, и просил помощи: «Нынче нашу землю взяли, а завтра вашу». Не терпя спокойной жизни, тот принялся подбивать князей на поход в степи.", "x": "Хан *@{kotyan|Котян}* был тестем Мстислава Удатного, князя Галича. Он ушёл к зятю просить заступничества: «Нынче нашу землю взяли, а завтра вашу».\n\n@{mstislav_ud|Удатный}, сын @{mstislav_hrab|Мстислава Храброго}, не терпел спокойной жизни. Он сам сел в Галиче, победив венгров и поляков, и выдал дочь за юного волынского князя @{daniil|Даниила}. Теперь он начал подбивать князей на *поход в степи*."}, {"r": ["Галич", "Киев"], "k": "trade", "n": "апр. 1223 · совет князей в Киеве", "b": "В Киеве собрались @{mstislav_roman|Мстислав Киевский}, @{mstislav_cherm|Мстислав Черниговский}, Удатный и @{daniil|Даниил}. Явились послы @{chingis|Чингис-хана}: монголы воюют только с половцами. Послов предали смерти, и за это князья потом заплатят дорогой ценой.", "x": "В Киеве собрались *@{mstislav_roman|Мстислав Романович}* Киевский, племянник @{rurik_rost|Рюрика Ростиславича} и самый старший из князей, @{mstislav_cherm|Мстислав Святославич} Черниговский, @{mstislav_ud|Удатный} и @{daniil|Даниил Романович}, его зять.\n\nВ Киев явились послы @{chingis|Чингис-хана} с мирными предложениями: монголы будут воевать только против половцев, а Русь не тронут. Послов предали смерти. За это злодеяние князья потом заплатят *дорогой ценой*."}, {"r": ["Киев", "Хортица"], "k": "war", "n": "весна 1223 · сбор на Хортице", "b": "На Хортице к русским дружинам присоединились половцы. Черниговцы выставили самую большую дружину, а монголы восемь дней отступали, уводя русских всё дальше от Днепра.", "x": "Хортица была местом сбора: туда пришли дружины @{mstislav_roman|Мстислава Киевского}, @{mstislav_cherm|Мстислава Черниговского}, @{mstislav_ud|Мстислава Удатного} и @{daniil|Даниила Волынского}. На Хортице к русским присоединились *половцы*. Черниговские князья выставили самую большую дружину и понесли самые тяжёлые потери.\n\nМонголы отступали *восемь дней*, и русские гнали их всё дальше от Днепра."}, {"r": ["Хортица", "Калка"], "k": "war", "n": "31 мая 1223 · Калка", "b": "Монголы остановились и дали бой. Удатный, как обычно, первым ринулся в сражение, но противник оказался невиданно силён. Половцы побежали и смяли русские ряды, погибло шесть князей, среди них @{mstislav_cherm|Мстислав Черниговский} с сыном.", "x": "*31 мая* монголы остановились и дали бой. @{mstislav_ud|Удатный}, как обычно, первым ринулся в сражение, но противник оказался невиданно силён. Половцы побежали и смяли русские ряды.\n\nПогибло *шесть князей*, среди них @{mstislav_cherm|Мстислав Черниговский} и его старший сын. По летописи, домой вернулся каждый десятый.\n\nТак русские князья, по Акунину, показали монголам, что они *не слишком опасные* противники."}, {"r": ["Калка", "Хортица"], "k": "flight", "n": "после Калки · Днепр и доски", "b": "Бежавшие к Днепру не смогли переправиться: Удатный пожёг все ладьи. Мстислава Киевского выдали, и его с зятьями положили под доски и сели на них пировать. Монголы ушли на Волгу и вернулись в 1237 году, уже за Русью.", "x": "Дружины одна за другой бежали к Днепру, но переправиться не могли: @{mstislav_ud|Удатный}, отступая, пожёг все *ладьи*.\n\n@{mstislav_roman|Мстислав Киевский} три дня сидел в укреплённом лагере и сдался по обещанию *@{plosknya|Плоскини}*. Его выдали, и вместе с зятьями положили под доски и сели на них пировать. Взятых в плен князей казнили в отместку за убитых послов.\n\nМонголы ушли на Волгу и вернулись в *1237* году."}], "pin": [["Калка", "здесь погибли шесть князей"], ["Хортица", "сбор русских и половцев"]], "zone": ["Половецкая степь", "Киевское"]},
  "Батый на северо-востоке": {"f": [["князья", "Юрий Игоревич Рязанский, Юрий Всеволодович Владимирский"], ["Рязань", "16–21 дек. 1237 · штурм на шестой день"], ["Владимир", "7 февр. 1238 · взят, семья князя сожжена"], ["Сить", "4 марта 1238 · гибель великого князя Юрия"], ["Торжок", "5 марта 1238 · две недели осады"], ["Козельск", "семь недель, «злой город»"]], "who": [["Батый", "Булгар", "хан монголов", "Сжёг Булгарию, в декабре 1237 осадил Рязань и за зиму взял около четырнадцати городов.", "batyi"], ["Юрий Игоревич", "Рязань", "князь Рязани", "Отказал Батыю в десятине. Погиб при штурме города 21 декабря 1237 вместе с семьёй.", "yuri_igor"], ["Юрий Всеволодович", "Владимир", "великий князь Владимира", "Не помог Рязани, потом ушёл на Сить собирать полки и погиб в бою 4 марта 1238.", "yuri_vsev"], ["Всеволод Юрьевич", "Владимир", "сын Юрия Всеволодовича", "Разбит под Коломной, затем оборонял Владимир. Город взят 7 февраля 1238.", "vsevolod_yur2"], ["Василий", "Козельск", "малолетний князь Козельска", "Его город Батый назвал «злым».", "vasiliy_koz"]], "ar": [{"r": ["Булгар", "Рязань"], "k": "war", "n": "дек. 1237 · Рязань", "b": "Монголы потребовали десятину от всего, и князь @{yuri_igor|Юрий Игоревич} отказал. Помощи от великого князя он не получил. Осада началась 16 декабря, а 21-го город взяли штурмом, и @{yuri_vsev|Юрий} погиб с семьёй.", "x": "Осенью *1236* года @{batyi|Батый} сжёг Волжскую Булгарию. Зимой монголы потребовали у рязанцев десятину от всего, и князь @{yuri_igor|Юрий Игоревич} отказал.\n\nОн просил помощи у великого князя Владимирского @{yuri_vsev|Юрия Всеволодовича}, сына @{vsevolod_bg|Всеволода Большое Гнездо}, но тот не помог. С 16 декабря город осаждали, на шестой день, *21 декабря*, взяли штурмом. Рязанский князь погиб с семьёй."}, {"r": ["Рязань", "Коломна", "Москва"], "k": "war", "n": "янв. 1238 · Коломна и Москва", "b": "Навстречу вышло владимирское войско @{vsevolod_yur2|Всеволода Юрьевича}, сына великого князя, и под Коломной было разбито. Москву осаждали пять дней и взяли в январе 1238 года. Горела она и раньше, в 1176-м.", "x": "Навстречу вышло владимирское войско под началом *@{vsevolod_yur2|Всеволода Юрьевича}*, сына великого князя. Под Коломной оно было разбито, а князь @{roman_ing|Роман Ингваревич} убит.\n\nМоскву осаждали пять дней. Она горела и раньше: в 1176 году её сжёг @{mstislav_rost|Мстислав Ростиславич} с @{gleb_rost|Глебом Рязанским}, а в январе *1238* года её взяли монголы."}, {"r": ["Москва", "Владимир"], "k": "war", "n": "7 февр. 1238 · Владимир", "b": "Великий князь уехал собирать полки, оставив в городе семью и разбитого сына. 7 февраля Владимир взяли, а жена и дети князя сгорели в Успенском соборе, который строил ещё @{andrey_bogol|Андрей Боголюбский}.", "x": "*3 февраля* монголы подошли к Владимиру. Великий князь @{yuri_vsev|Юрий Всеволодович} уехал собирать полки, оставив в городе семью и сына @{vsevolod_yur2|Всеволода}, разбитого под Коломной. Город остался без главы войска.\n\n*7 февраля* город взяли. Жена и дети великого князя сгорели в Успенском соборе, который строил ещё @{andrey_bogol|Андрей Боголюбский}."}, {"r": ["Владимир", "Сить"], "k": "war", "n": "4 марта 1238 · Сить", "b": "@{yuri_vsev|Юрий Всеволодович} стоял на реке Сить и собирал полки, но монголы настигли его, и он погиб в бою. Владимирские князья после этого надолго стали вассалами золотоордынских ханов.", "x": "@{yuri_vsev|Юрий Всеволодович} стоял на реке *Сить* и собирал полки. Монголы настигли его 4 марта, и великий князь погиб в бою.\n\nВладимирская земля после смерти @{vsevolod_bg|Всеволода Большое Гнездо} распалась на уделы. Великий князь не сумел собрать достаточно войска, и владимирские князья надолго стали вассалами *золотоордынских ханов*."}, {"r": ["Владимир", "Торжок"], "k": "war", "n": "5 марта 1238 · Торжок", "b": "Монголы взяли Торжок, принадлежавший Новгороду. До самого Новгорода оставалось меньше ста вёрст, но в конце марта из-за весенней распутицы они повернули назад.", "x": "*Торжок* принадлежал Новгороду и стоял на пути к нему. Ещё в 1178 году его осаждал @{vsevolod_bg|Всеволод Большое Гнездо}: он сжёг город, но жителей не перебил, а лишь взял в плен.\n\nМонголы взяли Торжок *5 марта*. Новгород оставался меньше чем в ста верстах, но в конце марта из-за весенней распутицы они повернули назад."}, {"r": ["Торжок", "Козельск"], "k": "war", "n": "апр.–май 1238 · Козельск", "b": "Малолетний князь @{vasiliy_koz|Василий} держал Козельск семь недель, куда дольше Рязани. @{batyi|Батый} назвал его «злым городом» и вырезал всех жителей. Северо-восток лежал в развалинах, Орда ушла в степь, а у юга оставалось ещё два года.", "x": "Козельск принадлежал малолетнему князю *@{vasiliy_koz|Василию}*. Город держался семь недель, куда дольше Рязани, взятой на шестой день осады, и @{batyi|Батый} назвал его «злым городом». Он вырезал всех жителей.\n\nЗа зиму и весну монголы взяли около четырнадцати городов северо-востока. Новгород остался цел и позже не был разорён *Ордой*."}], "pin": [["Рязань", "взята на шестой день осады"], ["Владимир", "семья князя сгорела в соборе"], ["Козельск", "вырезан весь город"]], "zone": ["Муромо-Рязанское", "Владимиро-Суздальское"]},
  "Падение Киева": {"f": [["оборона", "воевода Дмитр, горожане"], ["штурм", "пороки у Лядских ворот; последний бой в Десятинной церкви"], ["дата", "6 дек. 1240"], ["раньше", "Переяславль 3 марта 1239, Чернигов 18 окт. 1239"], ["Плано Карпини", "1246: в Киеве около 200 домов"], ["дальше", "Владимир-Волынский, Галич, затем Венгрия и Польша"]], "who": [["Батый", "Половцы", "хан монголов", "Взял Переяславль и Чернигов, потом осадил Киев и пошёл дальше на Волынь, Галич и Венгрию.", "batyi"], ["Дмитр", "Киев", "воевода Киева", "Оставлен Даниилом защищать город. Ранен и взят в плен, Батый пощадил его за храбрость.", "dmitr"], ["Михаил Всеволодович", "Киев", "князь Чернигова и Киева", "Бежал в Венгрию ещё до штурма.", "mikhail_vsev"], ["Даниил Романович", "Владимир-Волынский", "князь Галича и Волыни", "Оставил в Киеве Дмитра, сам ушёл в Венгрию и Польшу.", "daniil"]], "ar": [{"r": ["Половцы", "Переяславль"], "k": "war", "n": "3 марта 1239 · Переяславль", "b": "Два года @{batyi|Батый} воевал в степи против половцев и аланов, и @{kotyan|Котян} увёл в Венгрию сорок тысяч всадников. Потом очередь дошла до юга Руси: Переяславль, где когда-то княжил @{monomakh|Мономах}, пал 3 марта 1239 года.", "x": "После разорения северо-востока @{batyi|Батый} два года воевал в степи против половцев и аланов. Половцы бежали на запад: хан *@{kotyan|Котян}* увёл в Венгрию сорок тысяч всадников. Отдельные курени разбрелись, кто осел на Руси, кто в Закавказье, кто на Балканах.\n\nПереяславль, где когда-то княжил @{monomakh|Мономах}, пал 3 марта *1239* года."}, {"r": ["Переяславль", "Чернигов"], "k": "war", "n": "18 окт. 1239 · Чернигов", "b": "Чернигов, второй город Руси и оплот Ольговичей, пал после разгрома князя Мстислава Глебовича и был сожжён. Север земли разорили в 1238 году, юг в 1239-м, а часть сил Черниговщина потеряла ещё на Калке.", "x": "Чернигов был вторым по значению городом Руси и оплотом Ольговичей, потомков @{oleg_gor|Олега Гориславича}. Князь *@{mstislav_gleb|Мстислав Глебович}* был разбит, город сожжён.\n\nЧерниговщина уже пострадала на Калке, где погиб князь @{mstislav_cherm|Мстислав} с сыном. В 1238 и 1239 годах сначала северная, а затем южная половина земли подверглись *тотальному разорению*."}, {"r": ["Киев", "Венгрия"], "k": "flight", "n": "осень 1240 · Михаил бежит из Киева", "b": "Послов @{batyi|Батыя}, пришедших к Киеву, убили, а @{mikhail_vsev|Михаил Всеволодович} бежал в Венгрию ещё до штурма. @{daniil|Даниил}, занявший город раньше, ушёл в Венгрию и Польшу и оставил воеводой @{dmitr|Дмитра}, который и возглавил оборону.", "x": "*@{mikhail_vsev|Михаил Всеволодович}* был князем Чернигова и занимал Киев. Осенью 1240 года к городу пришли послы @{batyi|Батыя} с требованием сдаться, и их убили. Михаил бежал в Венгрию ещё до штурма.\n\n@{daniil|Даниил Романович}, сын Романа Галицкого, ещё до нашествия занял Киев и оставил там воеводой *@{dmitr|Дмитра}*. Сам он ушёл в Венгрию и Польшу, а оборону возглавил Дмитр."}, {"r": ["Чернигов", "Киев"], "k": "war", "n": "6 дек. 1240 · падение Киева", "b": "Киев уже разоряли суздальцы Андрея в 1169-м и свои князья в 1203-м. @{batyi|Батый} довёл дело до конца: «пороки» пробили стену у Лядских ворот, свод Десятинной церкви рухнул под защитниками, а раненого Дмитра он пощадил.", "x": "«Пороки», осадные орудия, пробили стену у *Лядских ворот*, и 6 декабря город пал. Последние защитники укрылись в Десятинной церкви, и свод рухнул под тяжестью людей. Раненого @{dmitr|Дмитра} @{batyi|Батый} пощадил за храбрость.\n\nКиев уже страдал от разгромов: в 1169 году его грабили суздальцы @{andrey_bogol|Андрея}, в *1203* году свои же князья. Батый довёл дело до конца."}, {"r": ["Киев", "Владимир-Волынский"], "k": "war", "n": "дек. 1240 · Батый идёт на Волынь", "b": "@{batyi|Батый} двинулся на Волынь, по земле @{daniil|Даниила}. Киев давно перестал быть центром власти и остался лишь религиозным пунктом, а теперь его уничтожили: @{karpini|Плано Карпини} через шесть лет нашёл там около двухсот домов и груды черепов.", "x": "Через шесть лет, в *1246* году, @{karpini|Плано Карпини} нашёл в Киеве около двухсот домов и множество черепов и костей.\n\n@{batyi|Батый} после Киева двинулся на запад, на Волынь, по земле @{daniil|Даниила Романовича}. Киев давно перестал быть главным центром власти, после 1169 года он оставался лишь важным религиозным пунктом, а теперь его *уничтожили*."}, {"r": ["Владимир-Волынский", "Галич"], "k": "war", "n": "зима 1241 · Галич и Даниил", "b": "Монголы лишь краем зацепили Галицию, и основная часть владений @{daniil|Даниила} уцелела. Он не воевал, а договаривался: поехал в Орду, признал себя вассалом и выговорил условия, так что баскаки за данью не приезжали.", "x": "Дальше Батый пошёл на *Венгрию* и Польшу. Монголы лишь краем зацепили Галицию, поэтому основная часть владений @{daniil|Даниила} осталась цела.\n\nДаниил не воевал с монголами, а договаривался: лично поехал в Орду и признал себя вассалом, но выговорил условия. Татарских гарнизонов в его землях не стояло, баскаки за *данью* не приезжали."}], "pin": [["Киев", "пал 6 дек.; бой в Десятинной"]], "zone": ["Киевское", "Переяславское", "Черниговское"]},
  "Выбор веры": {"ar": [{"r": ["Булгар", "Киев"], "k": "trade", "n": "986 · булгары, римляне и иудеи зовут князя в свою веру", "b": "Булгары сулили рай с женами, и это князю нравилось, но обрезание и отказ от вина его не устроили. Римляне с нестрогим постом его не впечатлили, а иудеям он заметил, что Бог рассеял их по чужим землям.", "x": "В 986 году к Владимиру вдруг явились представители четырёх основных вер, и каждый звал князя к своей.\n\nВолжские булгары соблазняли мусульманским раем, где праведники будут «с женами похоть творити блудную». Это распутному Владимиру нравилось, но смущало обрезание и запрет на свинину, а больше всего отказ от алкоголя. Тут он и произнёс, вероятно, самые известные слова русской истории: «Веселье Руси есть пити, не можем без того быти».\n\nПосланцы Рима говорили, что в их вере пост нестрогий, ешь и пей сколько хочешь, и князь не впечатлился. Хазарские иудеи начали хвалиться, что распяли христианского бога. Владимир ответил: «Если бы Бог любил вас и закон ваш, то не были бы вы рассеяны по чужим землям. Или и нам того же хотите?»"}, {"r": ["Константинополь", "Киев"], "k": "trade", "n": "986 · греческий философ показывает Страшный суд", "b": "Грек сперва бранил соперников, потом прочёл длинную лекцию о христианстве и показал картину Страшного суда. «Хорошо этим, справа, и плохо тем, что слева», сказал князь, но креститься не стал: «Пожду еще мало».", "x": "С греческим «философом» Владимир говорил совсем иначе. Тот, как водится, сначала бранил конкурентов. Про мусульман лгал, будто они, «подмывшись, вливают эту воду в рот, мажут ею по бороде и поминают Магомета», и Владимир плевался. Римскую церковь упрекал за службу на опресноках, но этих тонкостей князь не замечал.\n\nПотом началась длинная лекция о христианстве, которую князь перебивал сочувственными вопросами. Закончилась беседа картиной Страшного суда: справа праведники в раю, слева грешники в аду. Владимир заметил: «Хорошо этим, справа, и плохо тем, что слева».\n\nКрестись, сказал грек, и будешь справа. Но князь ответил: «Пожду еще мало» и отпустил византийца с честью."}, {"r": ["Киев", "Булгар", "Германия", "Константинополь"], "k": "trade", "n": "987 · десять мужей смотрят, как молятся у других", "b": "Бояре посоветовали не верить на слово, и десять «мужей добрых и смысленных» съездили к булгарам, «немцам» и грекам. Красоты греческой службы они забыть не смогли. Князь задумался, где креститься, но всё медлил, пока повод не дал византийский император.", "x": "На следующий год Владимир собрал «бояр своих и старцев градских», чтобы решить, какую веру выбрать. Те предложили не верить никому на слово, а съездить и посмотреть, как служат Богу в разных землях.\n\nПосольство из десяти «мужей добрых и смысленных» отправилось к булгарам, к «немцам» и к грекам. К хазарам они не поехали, и можно заключить, что иудаизм отсеялся ещё на первом этапе.\n\nБольше всего поразило греческое богослужение: «Не можем мы забыть красоты той, ибо каждый человек, если вкусит сладкого, не возьмёт потом горького». Владимир вроде бы согласился и даже задумался, где ему принять крещение, но по-прежнему медлил."}]},
  "Мятеж против отца": {"ar": [{"r": ["Киев", "Вышгород"], "k": "war", "n": "1014 · Владимир берёт Святополка под стражу", "b": "Князь назвал преемником любимого младшего @{boris|Бориса}, а @{svyatopolk_ok|Святополка}, с которым не ладил, посадил под стражу в Вышгородском замке близ Киева.", "x": "Княжичи были от разных матерей и жили во вражде, и Владимир, всю жизнь укреплявший государство, попытался предотвратить неминуемую схватку после своей смерти. Закона о престолонаследии он не придумал: на Руси тогда вообще не было законотворчества, и князь просто назначал наследника по своей воле.\n\nАнна родила ему только дочерей. С неродным Святополком, старшим из сыновей, отношения были скверные, поэтому Владимир выбрал Бориса, сына «болгарыни». Это случилось, видимо, в 1014 году.\n\nСвятополка и Ярослава это взбесило: первый рассчитывал на старшинство, второй был старшим из родных детей. Самого опасного, Святополка, князь велел схватить и держать в Вышгородском замке."}, {"r": ["Скандинавия", "Новгород"], "k": "war", "n": "1014 · Ярослав и Святополк ищут союзников", "b": "Новгород стоял за своего князя, и @{yaroslav_mudry|Ярослав} перестал платить отцу две трети дани, три тысячи гривен, и нанял варягов. @{svyatopolk_ok|Святополк}, женатый на дочери @{boleslav_hr|Болеслава} Храброго, мог рассчитывать на тестя и печенегов.", "x": "Новгород, ревниво относившийся к Киеву, стоял горой за своего князя Ярослава. Тот был обязан отдавать Владимиру две трети собираемой дани, три тысячи гривен, но теперь перестал и нанял за морем сильную варяжскую дружину.\n\nСвятополк Туровский годом раньше женился на дочери польского правителя Болеслава Храброго и мог надеяться на воинственного тестя, а тот к тому же был союзником печенегов. Когда Святополк оказался под стражей, Болеслав двинулся ему на помощь и позвал печенегов."}, {"r": ["Киев", "Новгород"], "k": "war", "n": "1015 · Владимир готовится идти на Новгород и умирает", "b": "@{boris|Бориса} с дружиной князь послал против печенегов, а сам велел расчищать дороги и строить мосты для похода на Новгород. Он не спешил: в стане врагов не было единства. 15 июля 1015 года @{vladimir|Владимир} скоропостижно умер.", "x": "Владимир готовился к войне с Ярославом неспешно: он, видимо, знал, что в неприятельском лагере нет единства и долго варяги с новгородцами не уживутся. Против печенегов, поддержавших Святополка, князь послал сильное войско во главе с Борисом.\n\nСам он приказал расчищать дороги и строить мосты для похода на Новгород. Но тут вдруг разболелся и 15 июля 1015 года скоропостижно скончался в своём загородном дворце.\n\nЕсли бы не эта смерть, смуту подавили бы, и Борис занял бы отцовский стол без серьёзных осложнений. Но воле покойного не суждено было осуществиться."}]},
  "Гибель Изяслава": {"ar": [{"r": ["Киев", "Краков"], "k": "flight", "n": "1073 · братья изгоняют Изяслава во второй раз", "b": "Получив Киев благодаря младшим братьям, @{izyaslav_yar|Изяслав} оказался от них зависим. В 1073 году они выступили вместе, он сдался без боя и увёз в Польшу казну, но король дары принял, а войска не дал.", "x": "Получив Киев с помощью младших братьев, @{izyaslav_yar|Изяслав} оказался от них зависим. Скоро у @{svyatoslav_yar|Святослава} и @{vsevolod_yar|Всеволода} появилось искушение избавиться от слабого правителя, и в 1073 году они выступили против него вместе.\n\nИзяслав опять сдался без боя. Он забрал всю богатую казну и с семьёй уехал в Польшу: рассчитывал снова получить помощь и искупить прежние вины перед королём щедрыми дарами. @{boleslav_sm|Болеслав} подношения от шурина принял, а войска не дал.\n\nНачались унизительные скитания по европейским дворам. Император Генрих IV, которому Изяслав тоже дарил богатые подарки, ограничился письменным увещеванием в Киев. Тогда изгнанник стал молить о покровительстве папу Григория VII и обещал подчинить русскую церковь Риму."}, {"r": ["Краков", "Киев", "Чернигов"], "k": "war", "n": "1076–1078 · третье княжение и гибель Изяслава", "b": "В 1076 году внезапно умер @{svyatoslav_yar|Святослав}, и король @{boleslav_sm|Болеслав II} решил, что помочь свойственнику теперь не опасно. @{izyaslav_yar|Изяслав} пошёл на Киев с польским войском, а @{vsevolod_yar|Всеволод} без боя уступил ему стол. Изяслав сел в третий раз, но в 1078-м пал от копья в стычке с племянником @{oleg_gor|Олегом}. Дальше правил Всеволод, последний из Ярославичей: в старости он много болел, не вникал в дела, и тиуны грабили народ. Умер он в 1093 году.", "x": "В 1076 году новый великий князь @{svyatoslav_yar|Святослав} внезапно умер от неудачной операции: ему «разрезали желвак». Болеслав решил, что теперь помогать свойственнику не рискованно, и дал Изяславу польское войско.\n\nВ Киеве уже сидел @{vsevolod_yar|Всеволод}, но сопротивляться не посмел и уступил верховенство старшему брату. Изяслав стал великим князем в третий раз, ненадолго.\n\nВ 1078 году в Черниговскую землю явился требовать своей доли Святославов сын @{oleg_gor|Олег}. Дядья разбили его дружину, но в кровопролитном бою Изяслав пал, сражённый ударом копья. Наследник Ярослава Мудрого сложил голову в малозначительной стычке с младшим родственником: так низко упал авторитет киевского князя."}]}
});
